// Everything that mirrors the settings in a module-level variable, refreshed together. A declared function, so
// register()'s apply, which the startup io hands out, assigns no outer variable itself (plain-names check 10).
function mirrorSettings(s: ReturnType<typeof settingsOf>): void {
  heldSettings = s
  mirror.queueOn = s.useReviewer
  mirror.cleanupMode = s.cleanup
  mirror.cleanupBase = s.base
  mirror.deployInfos = infosOf(s)
  mirror.maxManagers = s.maxManagers
  mirror.slotLimit = s.testSlots
  mirror.decisionPhrases = s.decisionPhrases
  mirror.preflightOn = s.preflight
  mirror.preflightWaitMs = s.preflightWait * 60_000
  mirror.askCards = s.askCards
}

export const register: Register = (on, options) => {
  // register()'s state, held by property: the hooks' ios read and write it here, so none hands out a closure
  // assigning an outer variable (plain-names check 10).
  const kept = {
    settings: settingsOf(renameOptions(options), 'main'),
    // Settings reloads: the files' paths and mtimes, the detected base branch, whether a check runs.
    paths: [] as string[],
    seen: '',
    detected: 'main',
    checking: false,
    // Set once a `[1m]` model was refused for a sub-agent: later spawns go straight to the plain one.
    noLong: false,
    // Set once the host refused a flow:continue rewrite: later continuations start in a new worktree.
    noContinue: false,
    // Main's model and window, to size a subagent that runs the same model.
    mainModel: undefined as string | undefined,
    mainWindow: undefined as number | undefined,
    // What the last drawing showed in place of the stored state while following, else null.
    paneFollow: null as { pick: string; cur: string } | null,
    // The version this plugin was installed as, read at session.start.
    installed: undefined as string | undefined,
  }
  mirrorSettings(kept.settings)
  // Reloaded settings: register()'s copy and the module-level mirror, together.
  const apply = (s: typeof kept.settings) => {
    kept.settings = s
    mirrorSettings(s)
  }
  // Reasoning effort per flow-started agent (agent.spawn decides, turn.step applies: the spawn input has no effort
  // field). The activity row keeps it across a plugin reload; effortSeen marks agents already looked up there.
  const agentEffort = new Map<string, string>()
  const effortSeen = new Set<string>()
  // Agent tool calls that named an `effort` themselves (by tool_use_id): an explicit effort wins over flow's.
  const explicitEffort = new Set<string>()
  // What /flow resume already handed to managers in this session.
  const resumed = new Set<string>()

  // The io (startup-run.ts) is written here in the hook, as 0.6.84 wrote the hook's body: no builder in between
  // (plain-names check 10).
  on('session.start', async ($, e, next) => {
    const io: StartupIo = {
      settings: () => kept.settings,
      applySettings: apply,
      paths: () => kept.paths, setPaths: p => { kept.paths = p },
      detected: () => kept.detected, setDetected: d => { kept.detected = d },
      seen: () => kept.seen, setSeen: x => { kept.seen = x },
      checking: () => kept.checking, setChecking: busy => { kept.checking = busy },
      installed: () => kept.installed, setInstalled: v => { kept.installed = v },
      options,
      pollMs: POLL_MS,
      prPollMs: PR_POLL_MS,
      initHint: INIT_HINT,
      best: (what, fn) => best($, what, fn),
      run: (argv, opts) => $.process.run(argv, opts),
      toast: text => { $.ui.toast(text) },
      every: (ms, fn) => { $.clock.every(ms, fn) },
      after: (ms, fn) => { $.clock.after(ms, fn) },
      now: () => $.clock.now(),
      relayMode: () => relayModeOf($),
      setRelay,
      locate: () => locate($),
      readText: path => readText($, path),
      mtime: path => mtimeOf($, path),
      // Written out field by field: the plugin directory confirms an agent leaves permissions with the user only
      // from an object literal in the call. These are the fields registerAgents (startup-run.ts) sets.
      registerAgent: spec => $.agent.register({ name: spec.name, description: spec.description, prompt: spec.prompt, model: spec.model, isolation: spec.isolation, background: spec.background }),
      registerCommand: spec => $.command.register(spec),
      registerTools: () => registerTools($),
      registerWorkerTools: () => registerWorkerTools($),
      resetDelivery: () => resetDelivery(text => toMain($, text)),
      resetStateDir,
      readState: async file => {
        const dir = await stateDir($)
        if (dir === undefined) return undefined
        return { disk: await readJson($, `${dir}/${file}`) }
      },
      loadHandovers: () => loadHandovers($),
      mergeHandovers: async disk => { await update($, handovers, hs => ({ ...disk, ...hs })) },
      autoSweep: () => autoSweep($),
      setInbox: async disk => { await update($, inbox, () => disk) },
      setBreaker: async disk => { await update($, reviewerBreaker, () => disk) },
      releaseHalt: async () => { await releaseHaltTo(breakerIoOf($), 'flow') },
      installedVersion: () => installedVersion($),
      handovers: () => read($, handovers),
      checks: () => read($, checks),
      setChecks: async disk => { await update($, checks, () => disk) },
      captureChecks: (ho, verifyPaths) => captureChecks($, ho, verifyPaths, false),
      markPrompted: async version => { await withChecks($, cur => ({ checks: { ...cur, promptedVersion: version }, out: undefined })) },
      setDeploys: async disk => { await update($, deploys, () => disk) },
      deployKnown: name => mirror.deployInfos.some(i => i.name === name),
      refreshBehind: () => void refreshBehind($),
      setPush: async disk => { await update($, pushState, () => disk) },
      setLite: async disk => { await update($, lite, () => disk) },
      mergeSessions: async raw => {
        const t = await $.clock.now()
        const disk = normalizeSessions(raw, t)
        await update($, sessions, cur => ({ ...disk, ...cur }))
      },
      snapshotSessions: async () => { roleState.saved = JSON.stringify(durableSessions(await read($, sessions))) },
      adoptSessions: () => adoptSessions($),
      setPreflight: async disk => { await update($, preflight, () => disk) },
      agents: () => agentsOf($),
      closePreflight: async (live, t) => { await withPreflight($, cur => { return { state: closeStale(cur, live, t), out: undefined } }) },
      setSlotDir,
      sh: (script, arg) => sh($, script, arg),
      relaySessionCount: async () => (await myRelaySessions($)).length,
      pump: () => void pumpOnce($, { settings: kept.settings, options, installed: kept.installed }),
      refresh: () => void refresh($),
      watchSessions: () => void watchSessions($),
      fetchPrs: () => void fetchPrs($),
      refreshLeftovers: () => refreshLeftovers($),
      tickNow: async () => {
        const t = await $.clock.now()
        await update($, now, () => t)
      },
      startReviewer: async () => void (await ensureQueue($)),
      clearDemo: async () => { await update($, demo, () => null) },
      firstRun: () => firstRun(initIoOf($)),
    }
    await startSession(io)
    return next(e)
  })

  // A closed pane stays closed: only this command and a newly started agent (openPane) open it,
  // never the roster poll, so `/flow close` holds while agents keep running.
  on('command.run', { command: 'flow' }, ($, e) => relay !== undefined ? { text: 'Run /flow in the main Claude Code session; this one only forwards its flow tools.' } : flowCommand(commandIoOf($), kept.settings, kept.installed, resumed, options, e.args, e.presentation?.columns))

  // Hands the request to the main session's model, which runs it with the dispatch skill. A
  // command can't submit a prompt itself (it would wait on its own turn), so a timer queues it
  // once the command has returned.
  on('command.run', { command: 'flow-tasks' }, async ($, e) => {
    if (relay !== undefined) return { text: 'Run /flow-tasks in the main Claude Code session.' }
    const args = e.args.trim()
    const text = `Use the flow:dispatch skill, "Tasks from a source": pick tasks from ${args ? `the task source and selection "${args}"` : 'this project\'s task source'} and start a manager for each.`
    $.clock.after(1, () => { void submitText($, text) })
    return { text: `Picking tasks${args ? ` from ${args}` : ''}.` }
  })

  // The plugin starts flow:continue itself through a rewrite. The host checks a rewrite's type against the
  // offer as listed (a hook that is offered only while it dispatches is too late for that check, and the host
  // then replays the refusal to a second next), so the type stays offered; a model's own spawn of it is denied below.
  on('agent.offer', { agent: CONTINUE }, () => ({ isOffered: true }))

  // The io (spawn-run.ts) is written here in the hook, as 0.6.84 wrote the hook's body (plain-names check 10).
  on('agent.spawn', ($, input, next) => {
    const io: SpawnHookIo = {
      relay: () => relay,
      settings: () => kept.settings,
      options: () => options,
      noLong: () => kept.noLong,
      setNoLong: () => { kept.noLong = true },
      noContinue: () => kept.noContinue,
      setNoContinue: () => { kept.noContinue = true },
      takeExplicit: id => explicitEffort.delete(id),
      setEffort: (id, effort) => { agentEffort.set(id, effort) },
      spawn: spawnIoOf($),
      now: () => $.clock.now(),
      agentList: () => $.agent.list(),
      plans: () => read($, plan),
      lite: () => read($, lite),
      gate: agentId => preflightGate($, agentId),
      jev: () => jevOf($, kept.settings),
      effortEnv: () => envOf($, 'CLAUDE_CODE_EFFORT_LEVEL'),
      toast: text => $.ui.toast(text),
      best: (what, fn) => best($, what, fn),
      refresh: () => refresh($),
      openPane: () => openPane($),
      updateActivity: fn => update($, activity, fn),
      changeLedger: fn => changeLedger($, fn),
      withLite: fn => withLite($, fn),
      withPreflight: fn => withPreflight($, fn),
      after: (ms, fn) => $.clock.after(ms, fn),
      sessions: () => read($, sessions),
      terminalSettings,
      startRoleSession: (p, s) => startRoleSession(sessionIoOf($), p, s),
    }
    return onSpawn(io, input, next)
  }).catch(($, e, next) => next(e))

  // Every tool call, the main session's too: refuse broad process kills and writes to the main
  // checkout. Then, for a subagent: refuse code edits from managers (a change goes into a
  // worker's brief), and keep the call as a line of the agent's activity log. The guards judge
  // before `next`, so the catch passes the call on only when the hook failed before it ran: a
  // broken guard must not block every call. A failure beneath `next` (a flow tool's own hook throwing)
  // reaches this catch, not the tool hook's own, so a flow tool that did not finish is answered here too.
  const toolCallHeld = { settings: () => kept.settings, explicitEffort, mainModel: () => kept.mainModel, mainWindow: () => kept.mainWindow }
  on('tool.call', async ($, e, next) => {
    if (relay !== undefined) return (await relayToolCallTo(relayRunIoOf($), kept.settings, e)) ?? next(e)
    if (e.tool.startsWith('mcp__flow__')) await noteReviewerReached($, e.agentId)
    const io = toolCallIoOf($, toolCallHeld)
    const refused = await beforeToolCall(io, e)
    if (refused !== undefined) return refused
    return afterToolCall(io, e, await next(e))
  }).catch((_$, e, next) => flowCatch(e, next))

  // In a relay copy nothing here may run: the generic hook above answers every flow tool through main,
  // and a call that got this far must not touch the copy's (empty) state.
  // The reviewer's tools: main, the reviewer, and a lite manager for its own PRs. A manager or worker otherwise is refused.
  // Release has its own hook building releaseIoOf($) in place, as 0.6.84 had it (plain-names check 10); a relayed call
  // reaches the same through runFlowTool. It answers a relay copy and a failure as the loop below does.
  on('tool.call', { tool: 'mcp__flow__release' }, async ($, e) => {
    if (relay !== undefined) return { result: 'flow relay: release did not reach the main session; try again.' }
    const input = e as unknown as FlowCall
    const refused = releaseToolAccess(await toolCallerOf($, e.agentId), input, await read($, handovers))
    if (refused !== undefined) return { result: refused }
    const out = await releaseTool(releaseIoOf($), kept.settings, input)
    return out!
  }).catch(toolCatch)

  // The reviewer and queue tools: the same access rule, and reviewerIoOf($) built in place, as 0.6.84 had it
  // (plain-names check 11). A relayed call reaches the same through runFlowTool.
  for (const tool of ['mcp__flow__reviewer', 'mcp__flow__queue'] as const) {
    on('tool.call', { tool }, async ($, e) => {
      if (relay !== undefined) return { result: `flow relay: ${tool.replace('mcp__flow__', '')} did not reach the main session; try again.` }
      const input = e as unknown as FlowCall
      const refused = reviewerToolAccess(await toolCallerOf($, e.agentId), input, await read($, handovers))
      if (refused !== undefined) return { result: refused }
      const out = await reviewerToolRun(reviewerIoOf($, kept.settings.base), kept.settings, input, e.agentId)
      return out!
    }).catch(toolCatch)
  }

  // guard_tests, note, clean, session, deploy and push: each its own hook with its body written in it, as 0.6.84 had
  // them. Through runFlowTool, a case io's closure calling a helper that wraps another closure took `$` 6 hops from
  // the hook, deeper than 0.6.84 ever went (5), and the plugin directory flagged it (plain-names check 13). A relayed
  // call reaches the same through runFlowTool's inline cases. Each answers a relay copy and a failure as the loop below does.
  on('tool.call', { tool: 'mcp__flow__guard_tests' }, async ($, e) => {
    if (relay !== undefined) return { result: 'flow relay: guard_tests did not reach the main session; try again.' }
    // The body is guardTestsCase's (toolcall-run.ts), shared with the relayed case; its io is written here, in the hook,
    // as 0.6.84's size_ab_report hook wrote its own.
    const io: GuardTestsCaseIo = {
      sessions: () => read($, sessions),
      agents: () => $.agent.list(),
      exec: argv => $.process.run(argv),
      cwd: () => $.session.cwd(),
    }
    const out = await guardTestsCase(io, kept.settings.base, kept.settings.guardTests, e as unknown as FlowCall)
    return out
  }).catch(toolCatch)

  on('tool.call', { tool: 'mcp__flow__note' }, async ($, e) => {
    if (relay !== undefined) return { result: 'flow relay: note did not reach the main session; try again.' }
    const input = e as unknown as FlowCall
    const manager = String(input.manager ?? '').trim()
    if (manager === '') return { result: 'Refused: manager (your agent name) is required.' }
    const text = typeof input.text === 'string' ? input.text.trim() : ''
    if (text === '') {
      const notes = await readNotes($, manager)
      return { result: notes === '' ? 'No notes yet.' : notes }
    }
    const now = await $.clock.now()
    const date = new Date(now).toISOString().slice(0, 10)
    const line = input.kind === 'decision' ? `- ${date} decision: "${text}"` : `- ${date} progress: ${text}`
    if (!await appendNote($, manager, line)) return { result: 'Not saved: notes need a repo (or the write failed; see the UI log).' }
    await best($, 'logging a note', () => appendLog($, { event: 'note', owner: noteKey(manager), text }))
    return { result: `Noted in ${await notesPath($, manager)}.` }
  }).catch(toolCatch)

  on('tool.call', { tool: 'mcp__flow__clean' }, async ($, e) => {
    if (relay !== undefined) return { result: 'flow relay: clean did not reach the main session; try again.' }
    const apply = (e as unknown as FlowCall).apply === true
    if (apply && kept.settings.cleanup === 'off') {
      return { result: `Cleanup is off (the cleanup setting): a dry run instead, nothing removed. A person removes with /flow clean --yes.\n${await sweep($, kept.settings.base, false)}` }
    }
    return { result: await sweep($, kept.settings.base, apply) }
  }).catch(toolCatch)

  on('tool.call', { tool: 'mcp__flow__session' }, async ($, e) => {
    if (relay !== undefined) return { result: 'flow relay: session did not reach the main session; try again.' }
    const id = e.agentId
    const caller: Caller = id === undefined ? { id: 'main', name: 'main' } : { id, name: await ownerNameOf($, id) }
    return { result: await sessionTool($, e as unknown as FlowCall, caller, kept.settings) }
  }).catch(toolCatch)

  on('tool.call', { tool: 'mcp__flow__deploy' }, async ($, e) => {
    if (relay !== undefined) return { result: 'flow relay: deploy did not reach the main session; try again.' }
    const input = e as unknown as FlowCall
    const isMain = e.agentId === undefined
    const caller = isMain ? 'main' : await ownerNameOf($, e.agentId)
    const refused = deployToolAccess(await toolCallerOf($, e.agentId), input, await read($, handovers))
    if (refused !== undefined) return { result: refused }
    return { result: await deployTool($, options, input, isMain, caller) }
  }).catch(toolCatch)

  on('tool.call', { tool: 'mcp__flow__push' }, async ($, e) => {
    if (relay !== undefined) return { result: 'flow relay: push did not reach the main session; try again.' }
    const input = e as unknown as FlowCall
    if (e.agentId !== undefined) return { result: PUSH_REFUSED }
    const action = String(input.action ?? 'list')
    if (action === 'list') {
      const lines = pushLines(await read($, pushState))
      return { result: lines.length === 0 ? 'Nothing ready to push.' : lines.join('\n') }
    }
    if (action === 'push') return { result: await pushAct($, { kind: 'push' }, 'main') }
    if (action === 'drop') return { result: await pushAct($, { kind: 'drop' }, 'main') }
    if (action === 'send-back') {
      const pr = Number(input.pr)
      if (!Number.isInteger(pr) || pr <= 0) return { result: 'Refused: send-back needs pr, a PR number of the batch.' }
      return { result: await pushAct($, { kind: 'back', pr }, 'main') }
    }
    return { result: 'Unknown action: use list, push, send-back or drop.' }
  }).catch(toolCatch)

  // The tools above have their own hooks.
  const OWN_HOOK: readonly string[] = [
    'mcp__flow__release', 'mcp__flow__reviewer', 'mcp__flow__queue',
    'mcp__flow__guard_tests', 'mcp__flow__note', 'mcp__flow__clean', 'mcp__flow__session', 'mcp__flow__deploy', 'mcp__flow__push',
  ]
  for (const tool of FLOW_TOOLS.filter(t => !OWN_HOOK.includes(t))) {
    on('tool.call', { tool: tool as never }, async ($, e) => {
      if (relay !== undefined) return { result: `flow relay: ${tool.replace('mcp__flow__', '')} did not reach the main session; try again.` }
      const out = await runFlowTool($, tool, e as unknown as FlowCall, { settings: kept.settings, options, installed: kept.installed })
      return out!
    }).catch(toolCatch)
  }

  // Main can't be replaced like a worker: one warning per crossing, never an auto-compact.
  // Re-armed when usage drops back below the threshold (after a /compact).
  const mainWarn = { warned: false }

  // Context used by a subagent: the input side of its latest step. Observe only; the step passes untouched.
  // Main's model and window live in this closure; the usage module reads and sets them through these.
  const mainHeld = {
    mainModel: () => kept.mainModel,
    setMainModel: (m: string | undefined) => { kept.mainModel = m },
    mainWindow: () => kept.mainWindow,
    setMainWindow: (w: number) => { kept.mainWindow = w },
  }
  on('turn.step', async function* ($, e, next) {
    if (relay !== undefined) return yield* next(e)
    const step = await beforeStep(turnIoOf($, kept.settings, { agentEffort, effortSeen }), e)
    const r = yield* next(step)
    await meterStep(usageIoOf($, kept.settings, mainWarn, mainHeld), kept.settings, e, r)
    await countStep(usageIoOf($, kept.settings, mainWarn, mainHeld), e, r)
    return r
  })

  // Every completed turn (interrupted or errored too: it still wrote the cache) counts once per agent.
  const countedTurns = new Set<string>()
  on('turn.complete', async ($, e, next) => {
    if (relay !== undefined) return next(e)
    await countTurn(costIoOf($), countedTurns, e.agentId, (e as { turnId?: string }).turnId)
    await completeTurn(turnIoOf($, kept.settings, { agentEffort, effortSeen }), e)
    return next(e)
  })

  // The pane paints with theme keys, which the engine resolves; a theme switch only needs a redraw.
  on('config.set', { key: 'theme' }, async ($, e, next) => {
    const r = await next(e)
    try { $.ui.invalidate('ui.render') } catch { /* pane closed */ }
    return r
  })

  // Arrows and Tab move the focus ring over the cards; the highlight follows it (pane-run.tsx).
  // Each pane hook writes the io it needs in its body, as 0.6.84 did, with no builder taking `$` (plain-names check 11).
  on('ui.focus', { requestId: PANE }, async ($, e, next) => {
    const r = await next(e)
    const io: PaneFocusIo = {
      read: { roster: () => read($, roster) },
      set: {
        selected: fn => update($, selected, fn),
        cursor: fn => update($, cursor, fn),
        overrideView: fn => update($, overrideView, fn),
      },
      paneFollow: () => kept.paneFollow,
      paneView: () => paneView,
    }
    await paneFocus(io, e.element)
    return r
  })

  // Esc in the pane goes home from any sub-view. closeOnEscape makes the engine raise ui.close
  // (origin person) for it; answering without next keeps the pane open, so Esc never closes it.
  // inboxDraft stays: an unsent draft survives. A focused field keeps its own Esc (it only blurs).
  on('ui.close', { id: PANE }, async ($, e, next) => {
    if (e.origin.kind !== 'person') return next(e)
    await paneHome($)
    return { value: undefined }
  })

  // The wheel and PgUp/PgDn over an open card whose body is taller than its room move that body (pane-run.tsx);
  // the card's header and buttons stay put. Anywhere else the pane scrolls as the engine does it.
  on('ui.scroll', { requestId: PANE }, async ($, e, next) => {
    const io: PaneScrollIo = {
      set: { cardScroll: fn => update($, cardScroll, fn) },
      invalidate: () => paneInvalidate($),
    }
    const moved = await paneScroll(io, e.by, e.bodyRows)
    if (!moved) return next(e)
    return {}
  })

  // The pane draws in pane-run.tsx.
  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const io: PaneIo = {
      read: {
        roster: () => read($, roster),
        activity: () => read($, activity),
        selected: () => read($, selected),
        cursor: () => read($, cursor),
        folded: () => read($, folded),
        overrideView: () => read($, overrideView),
        hinted: () => read($, hinted),
        now: () => read($, now),
        handovers: () => read($, handovers),
        inbox: () => read($, inbox),
        checks: () => read($, checks),
        ledger: () => read($, ledger),
        leftovers: () => read($, leftovers),
        sessions: () => read($, sessions),
        harnessLimits: () => read($, harnessLimits),
        armed: () => read($, armed),
        deploys: () => read($, deploys),
        behind: () => read($, behind),
        pushState: () => read($, pushState),
        reviewerBreaker: () => read($, reviewerBreaker),
        plan: () => read($, plan),
        viewMode: () => read($, viewMode),
        prShown: () => read($, prShown),
        prBack: () => read($, prBack),
        batchPick: () => read($, batchPick),
        prDetails: () => read($, prDetails),
        inboxCursor: () => read($, inboxCursor),
        cardBack: () => read($, cardBack),
        inboxFolds: () => read($, inboxFolds),
        inboxOpen: () => read($, inboxOpen),
        inboxDraft: () => read($, inboxDraft),
        inboxNote: () => read($, inboxNote),
        graphFocus: () => read($, graphFocus),
        demo: () => read($, demo),
        cardScroll: () => read($, cardScroll),
      },
      set: {
        selected: fn => update($, selected, fn),
        cursor: fn => update($, cursor, fn),
        folded: fn => update($, folded, fn),
        overrideView: fn => update($, overrideView, fn),
        hinted: fn => update($, hinted, fn),
        armed: fn => update($, armed, fn),
        viewMode: fn => update($, viewMode, fn),
        prShown: fn => update($, prShown, fn),
        prBack: fn => update($, prBack, fn),
        batchPick: fn => update($, batchPick, fn),
        prDetails: fn => update($, prDetails, fn),
        inboxCursor: fn => update($, inboxCursor, fn),
        cardBack: fn => update($, cardBack, fn),
        inboxFolds: fn => update($, inboxFolds, fn),
        inboxOpen: fn => update($, inboxOpen, fn),
        inboxDraft: fn => update($, inboxDraft, fn),
        inboxNote: fn => update($, inboxNote, fn),
        graphFocus: fn => update($, graphFocus, fn),
        demo: fn => update($, demo, fn),
        cardScroll: fn => update($, cardScroll, fn),
      },
      resolve: ev => paneResolve($, ev),
      now: () => $.clock.now(),
      usage: () => paneUsage($),
      toast: text => { $.ui.toast(text) },
      invalidate: () => paneInvalidate($),
      after: (ms, fn) => { $.clock.after(ms, fn) },
      focus: key => paneFocusKey($, key),
      fill: text => $.prompt.fill({ text, mode: 'replace' }),
      runProcess: (argv, timeoutMs) => $.process.run(argv, { timeoutMs }),
      serial: paneSerial,
      settings: () => kept.settings,
      installed: () => kept.installed,
      mainModel: () => kept.mainModel,
      mainWindow: () => kept.mainWindow,
      setMainWindow: w => { kept.mainWindow = w },
      paneFollow: () => kept.paneFollow,
      setPaneFollow: f => { kept.paneFollow = f },
      paneView: () => paneView,
      setPaneView,
      unhanded: () => currentUnhanded($),
      endedOwners: () => endedOwnersOf($),
      demoArm: s => paneDemoArm($, s),
      demoMove: fn => paneDemoMove($, fn),
      demoStop: () => paneDemoStop($),
      pushAct: (act, by) => pushAct($, act, by),
      approve: n => paneApprove($, n),
      reject: (n, why) => paneReject($, n, why),
      platform: () => platformOf($),
      paneInboxRows: () => paneInboxRows($),
      suggestions: () => paneSuggestionsOf($, options),
      dismiss: ids => paneDismiss($, options, ids),
      answer: (id, choice) => answerQuestion($, id, choice, 'main', {}, true),
      sessionTool: input => paneSessionTool($, input, kept.settings),
    }
    return paneDraw(io, e)
  })
}

