import type { Handover } from '../types'
import { noteKey } from './state'

// Lite mode, the pure half: one task run as just a manager and its workers. A manager spawned with a
// `Mode: lite` line (preflight.ts isLite) is recorded here, gets the LITE rules block (prompts.ts), skips
// pre-flight and size decisions and merges its own PR instead of handing it
// to a reviewer agent. The disk half is in register.tsx.

export type LiteState = Record<string, { name: string; at: number }>

export const EMPTY_LITE: LiteState = {}

// Keyed by noteKey, so a successor (`x-2`) of a lite manager is lite too.
export const isLiteName = (state: LiteState, name: string | undefined): boolean =>
  name !== undefined && state[noteKey(name)] !== undefined

// The same object when the manager is already recorded.
export function recordLite(state: LiteState, name: string, at: number): LiteState {
  return isLiteName(state, name) ? state : { ...state, [noteKey(name)]: { name, at } }
}

// A stored record read back from disk; anything malformed is dropped.
export function normalizeLite(raw: unknown): LiteState {
  const out: LiteState = {}
  if (typeof raw !== 'object' || raw === null) return out
  for (const [k, v] of Object.entries(raw as Record<string, unknown>)) {
    const e = v as { name?: unknown; at?: unknown } | null
    if (typeof e === 'object' && e !== null && typeof e.name === 'string') out[k] = { name: e.name, at: typeof e.at === 'number' ? e.at : 0 }
  }
  return out
}

// The rules go in front of the manager's prompt once, however often the spawn is rewritten.
export const withLiteRules = (prompt: string, rules: string, mark: string): string =>
  prompt.includes(mark) ? prompt : `${rules}\n\n${prompt}`

export const LITE_USAGE = 'Usage: /flow lite <task>. Runs one task as just a manager and its workers (no pre-flight, no reviewer agent) to save tokens.'

// What /flow lite submits to main: commands cannot start agents themselves.
export function liteStartPrompt(task: string): string {
  return [
    'Start one flow:manager for the task below, in lite mode. Give it a short name slug of your own choosing and run it in the background.',
    'Its prompt is the task in the user\'s words, with the line "Mode: lite" on a line of its own. Add no other mode line and no "Size:" line unless the task is clearly a large one (then "Size: large"). Start nothing else for this task.',
    '',
    'Task:',
    task,
  ].join('\n')
}

// Who is calling a tool that used to belong to the reviewer alone.
export type ToolCaller = { kind: 'main' } | { kind: 'reviewer' } | { kind: 'lite'; name: string } | { kind: 'other' }

const prsOf = (input: Record<string, unknown>): number[] =>
  (Array.isArray(input.prs) ? input.prs : [input.pr]).map(Number).filter(n => Number.isInteger(n) && n > 0)

// The PRs a lite manager may act on: its own, recorded by the handover tool.
export const ownsLitePr = (h: Handover | undefined, name: string): boolean =>
  h !== undefined && h.lite === true && noteKey(h.reportTo) === noteKey(name)

const OTHER = (tool: string, why = 'it belongs to the reviewer') => `Refused: ${tool} is not for you; ${why}. Hand your PR over with mcp__flow__handover.`

// mcp__flow__reviewer / mcp__flow__queue. A lite manager may record a ready batch ("ready") or finish ("done") its own PR.
export function reviewerToolAccess(caller: ToolCaller, input: Record<string, unknown>, handovers: Record<string, Handover>): string | undefined {
  const action = String(input.action ?? '')
  if (action === 'list' || caller.kind === 'main' || caller.kind === 'reviewer') return undefined
  if (caller.kind === 'other') return OTHER('mcp__flow__reviewer')
  if (action !== 'ready' && action !== 'done') return 'Refused: a lite manager uses the reviewer tool only for "ready" and "done" on its own PR; "take" and "back" belong to the reviewer.'
  const prs = prsOf(input)
  if (prs.length === 0 || prs.some(n => !ownsLitePr(handovers[String(n)], caller.name))) {
    return 'Refused: a lite manager may only act on the PRs it handed over itself in lite mode.'
  }
  return undefined
}

// mcp__flow__release (cut and publish): the lite manager's own PRs only.
export function releaseToolAccess(caller: ToolCaller, input: Record<string, unknown>, handovers: Record<string, Handover>): string | undefined {
  if (caller.kind === 'main' || caller.kind === 'reviewer') return undefined
  if (caller.kind === 'other') return OTHER('mcp__flow__release')
  const own = Object.values(handovers).filter(h => ownsLitePr(h, caller.name))
  if (input.action === 'publish') return own.length === 0 ? 'Refused: publish only follows the release of a PR you handed over in lite mode.' : undefined
  const prs = prsOf(input)
  if (prs.length === 0 || prs.some(n => !ownsLitePr(handovers[String(n)], caller.name))) {
    return 'Refused: a lite manager may release only the PRs it handed over itself in lite mode.'
  }
  return undefined
}

// mcp__flow__deploy: gate, deployed and env-applied for a lite manager that has a PR of its own. list is read-only
// and hold/release stay main's (deployTool checks those itself).
export function deployToolAccess(caller: ToolCaller, input: Record<string, unknown>, handovers: Record<string, Handover>): string | undefined {
  const action = String(input.action ?? 'list')
  if (action === 'list' || action === 'hold' || action === 'release') return undefined
  if (caller.kind === 'main' || caller.kind === 'reviewer') return undefined
  if (caller.kind === 'other') return OTHER('mcp__flow__deploy')
  if (!Object.values(handovers).some(h => ownsLitePr(h, caller.name))) return 'Refused: a lite manager gates a deploy only for a PR it handed over itself in lite mode.'
  return undefined
}

files.hooks/checks.ts:
// The pure half of person checks: an after-deploy check that needs a person becomes a durable item the
// user closes as passed or failed. Captured from the reviewer's `needs a person: PR #<n>: <steps>` report
// line; kept in <state dir>/checks.json (the disk half is withChecks() in register.tsx). Separate from the
// decision inbox's questions (inbox.ts), shown alongside them.

import type { Check, Checks, FollowUp } from '../types'
import { renderTable, truncate } from './table'
import type { Column, Row } from './table'

export type { Check, Checks, FollowUp }

export const EMPTY_CHECKS: Checks = { next: 1, items: [] }

export type Needed = { pr: number; steps: string }

const MARK = /needs a person: PR #(\d+): ([^\n]*?)(?= \| |\n|$)/g

// The needs-a-person lines of a reviewer report; steps end at the next " | " or the end of the line.
export function parseNeeds(report: string | undefined): Needed[] {
  const out: Needed[] = []
  for (const m of (report ?? '').matchAll(MARK)) {
    const steps = (m[2] ?? '').trim()
    if (steps !== '') out.push({ pr: Number(m[1]), steps })
  }
  return out
}

export const normSteps = (s: string): string => s.toLowerCase().replace(/\s+/g, ' ').replace(/[.\s]+$/, '').trim()

// A version mentioned in the steps: "install 0.3.31" first, else any X.Y.Z.
export function versionInSteps(steps: string): string | undefined {
  return /\binstall(?:ed|ing)?\s+(?:plugin\s+)?v?(\d+\.\d+\.\d+)/i.exec(steps)?.[1] ?? /\bv?(\d+\.\d+\.\d+)\b/.exec(steps)?.[1]
}

const parts = (v: string): number[] => v.replace(/^v/, '').split('.').map(p => Number.parseInt(p, 10) || 0)

// Negative when a is older than b; numeric per dot-separated part.
export function compareVersions(a: string, b: string): number {
  const x = parts(a)
  const y = parts(b)
  for (let i = 0; i < Math.max(x.length, y.length); i++) {
    const d = (x[i] ?? 0) - (y[i] ?? 0)
    if (d !== 0) return d
  }
  return 0
}

// A path glob as a regex: ** crosses directories, * stays in one, ? is one character.
function globRe(g: string): RegExp {
  let s = ''
  for (let i = 0; i < g.length; i++) {
    const ch = g[i]!
    if (ch === '*' && g[i + 1] === '*') { s += '.*'; i++; if (g[i + 1] === '/') i++ }
    else if (ch === '*') s += '[^/]*'
    else if (ch === '?') s += '[^/]'
    else s += ch.replace(/[.+^${}()|[\]\\]/g, '\\$&')
  }
  return new RegExp(`^${s}$`)
}

// Whether any changed file matches any glob.
export const anyMatch = (globs: string[], files: string[]): boolean => {
  const res = globs.map(globRe)
  return files.some(f => res.some(r => r.test(f)))
}

export const SKIP_NOTE = 'scripted verification skipped: no changed file matches verify_paths'

export type NewCheck = { steps: string; version?: string; verifyCommand?: string; note?: string }

// Adds a check for each item unless the same PR and steps (normalised) already have one, of any state.
export function addChecks(cur: Checks, pr: number, title: string, sha: string | undefined, items: NewCheck[], now: number): { checks: Checks; added: Check[] } {
  const added: Check[] = []
  let next = cur.next
  const seen = new Set(cur.items.map(c => `${c.pr}|${normSteps(c.steps)}`))
  for (const it of items) {
    const key = `${pr}|${normSteps(it.steps)}`
    if (seen.has(key)) continue
    seen.add(key)
    added.push({
      id: `c${next++}`, kind: 'check', pr, title, steps: it.steps, ...(it.version !== undefined ? { version: it.version } : {}),
      ...(sha ? { sha } : {}), ...(it.verifyCommand ? { verifyCommand: it.verifyCommand } : {}), ...(it.note ? { note: it.note } : {}),
      createdAt: now, state: 'open',
    })
  }
  return added.length === 0 ? { checks: cur, added } : { checks: { ...cur, next, items: [...cur.items, ...added] }, added }
}

export const openChecks = (c: Checks): Check[] => c.items.filter(x => x.state === 'open')
export const openFollowUps = (c: Checks): Check[] => c.items.filter(x => x.state === 'failed' && x.followUp?.state === 'open')

export type Groups = { install: { version: string; items: Check[] }[]; ready: Check[]; none: Check[]; unknown: Check[] }

// Open checks by what they need: a newer version than installed (one group per version, ascending), the
// installed version or older, no version at all. With the installed version unknown, a versioned check is "unknown".
export function groupOpen(c: Checks, installed: string | undefined): Groups {
  const g: Groups = { install: [], ready: [], none: [], unknown: [] }
  const byVersion = new Map<string, Check[]>()
  for (const x of openChecks(c)) {
    if (x.version === undefined) g.none.push(x)
    else if (installed === undefined) g.unknown.push(x)
    else if (compareVersions(x.version, installed) <= 0) g.ready.push(x)
    else byVersion.set(x.version, [...(byVersion.get(x.version) ?? []), x])
  }
  g.install = [...byVersion.entries()].sort((a, b) => compareVersions(a[0], b[0])).map(([version, items]) => ({ version, items }))
  return g
}

const line = (c: Check) =>
  `  ${c.id} PR #${c.pr} ${c.title}: ${c.steps}${c.verifyCommand ? ` (scripted: ${c.verifyCommand})` : ''}${c.note ? ` [${c.note}]` : ''}`

function groupLines(g: Groups, installed: string | undefined): string[] {
  const out: string[] = []
  for (const x of g.install) out.push(`Needs install of ${x.version} and a restart:`, ...x.items.map(line))
  if (g.ready.length) out.push(`Ready on the installed version ${installed ?? '?'}:`, ...g.ready.map(line))
  if (g.unknown.length) out.push('Version unknown (the installed version could not be read):', ...g.unknown.map(line))
  if (g.none.length) out.push('No version:', ...g.none.map(line))
  return out
}

const followUpLine = (c: Check) => `  ${c.id} PR #${c.pr} ${c.title}: failed (${c.note ?? ''}). Start a manager on the follow-up with the PR, the steps (${c.steps}) and the note, then mcp__flow__check {"action":"started","id":"${c.id}","manager":"<name>"}.`

const FOLLOW = 'Open follow-ups from failed checks:'

// mcp__flow__check list and the agent-facing text: every step in full, and how main closes a check.
export function renderChecksForAgents(c: Checks, installed: string | undefined): string {
  const open = openChecks(c)
  const fu = openFollowUps(c)
  if (open.length === 0 && fu.length === 0) return 'No open checks.'
  return [
    ...(open.length ? [`Open checks: ${open.length}. Close with mcp__flow__check (action pass, fail or skip) or /flow checks pass <id...> | fail <id> <note> | skip <id...> <why>.`, ...groupLines(groupOpen(c, installed), installed)] : ['No open checks.']),
    ...(fu.length ? [FOLLOW, ...fu.map(followUpLine)] : []),
  ].join('\n')
}

// The "Checks" section of /flow inbox: the count and the same short grouping, or nothing when none are open.
export function inboxChecksSection(c: Checks, installed: string | undefined): string[] {
  const open = openChecks(c)
  const fu = openFollowUps(c)
  if (open.length === 0 && fu.length === 0) return []
  const g = groupOpen(c, installed)
  const bits = [
    ...g.install.map(x => `${x.items.length} need install of ${x.version}`),
    ...(g.ready.length ? [`${g.ready.length} ready`] : []), ...(g.unknown.length ? [`${g.unknown.length} version unknown`] : []),
    ...(g.none.length ? [`${g.none.length} no version`] : []),
  ]
  return [`Checks: ${open.length} open${bits.length ? ` (${bits.join(', ')})` : ''}${fu.length ? `, ${fu.length} follow-up${fu.length > 1 ? 's' : ''}` : ''}. /flow checks lists them.`]
}

// The one-line count on the Flow pane, or undefined when there is nothing open.
export function paneChecksLine(c: Checks, installed: string | undefined): string | undefined {
  const open = openChecks(c)
  const fu = openFollowUps(c)
  if (open.length === 0 && fu.length === 0) return undefined
  const g = groupOpen(c, installed)
  const need = g.install.reduce((n, x) => n + x.items.length, 0)
  const vers = g.install.map(x => x.version).join(', ')
  const waits = need ? ` (${need} wait for ${vers} to be installed)` : ''
  const parts = [
    ...(open.length ? [`${open.length} check${open.length === 1 ? '' : 's'} to try by hand${waits}`] : []),
    ...(fu.length ? [`${fu.length} failed check${fu.length === 1 ? '' : 's'} to hand to a manager`] : []),
  ]
  return `${parts.join(', ')}. /flow checks lists them`
}

// The /flow resume section: open checks are mentioned only; follow-ups are work for main to start.
export function resumeChecksLines(c: Checks, installed: string | undefined): string[] {
  const open = openChecks(c)
  const fu = openFollowUps(c)
  return [
    ...(open.length ? ['Open checks (for the user, nothing to start):', ...groupLines(groupOpen(c, installed), installed)] : []),
    ...(fu.length ? ['Open follow-ups from failed checks (start a manager on each):', ...fu.map(followUpLine)] : []),
  ]
}

// The open checks the installed version now covers, if it differs from the version the user was last notified of.
export function dueForPrompt(c: Checks, installed: string | undefined): Check[] {
  if (installed === undefined || c.promptedVersion === installed) return []
  return openChecks(c).filter(x => x.version !== undefined && compareVersions(x.version, installed) <= 0)
}

export const CHECKS_USAGE = 'Usage: /flow checks, /flow checks <id>, /flow checks pass <id...>, /flow checks fail <id> <what you saw>, /flow checks skip <id> <why>'

// A short age: minutes, hours or days.
const ago = (ms: number): string => {
  const m = Math.max(0, Math.round(ms / 60_000))
  return m < 60 ? `${m}m` : m < 1440 ? `${Math.round(m / 60)}h` : `${Math.round(m / 1440)}d`
}

const byId = (a: Check, b: Check) => Number(a.id.slice(1)) - Number(b.id.slice(1))

const COLS: Column[] = [
  { header: 'id' }, { header: 'PR' }, { header: 'title', flex: true },
  { header: 'needs', max: 14, drop: 2 }, { header: 'age', max: 4, drop: 1 },
]

const titleOf = (c: Check) => c.title === '' ? `PR #${c.pr}` : c.title

// The person view of /flow checks: one table, one row per open check, grouped by what it needs, then the open
// follow-ups of failed checks. Full steps are in the detail view, so rows never wrap.
export function renderChecksTable(c: Checks, installed: string | undefined, width: number, now: number, footer = true): string {
  const open = openChecks(c)
  const fu = openFollowUps(c)
  if (open.length === 0 && fu.length === 0) return 'No open checks.'
  const g = groupOpen(c, installed)
  const row = (x: Check, needs: string): string[] => [x.id, `#${x.pr}`, titleOf(x), needs, ago(now - x.createdAt)]
  const rows: Row[] = []
  const tryNow = [...g.ready, ...g.none].sort(byId)
  if (tryNow.length) rows.push('Try now', ...tryNow.map(x => row(x, 'ready')))
  for (const x of g.install) rows.push(`Needs install of ${x.version}`, ...x.items.map(i => row(i, `install ${x.version}`)))
  if (g.unknown.length) rows.push('Version unknown', ...g.unknown.map(x => row(x, '?')))
  if (fu.length) rows.push('Failed, follow-up open', ...fu.map(x => [x.id, `#${x.pr}`, `failed: ${x.note ?? ''} · ${titleOf(x)}`, '', ago(now - (x.closedAt ?? x.createdAt))]))
  const out = [`Checks: ${open.length} open${fu.length ? `, ${fu.length} failed with a follow-up` : ''}`, '', ...renderTable(COLS, rows, width)]
  if (footer) {
    const first = (open[0] ?? fu[0])!.id
    const ready = tryNow.map(x => x.id)
    // Only failed checks left: pass, fail and skip on them are refused, so show the detail command alone.
    const parts = open.length === 0 ? [`Details: /flow checks ${first}`] : [
      `Pass: /flow checks pass ${(ready.length ? ready.slice(0, 2) : [first]).join(' ')}`, `Fail: /flow checks fail ${first} <what you saw>`,
      `Skip: /flow checks skip ${first} <why>`, `Details: /flow checks ${first}`,
    ]
    const one = parts.join(' · ')
    out.push('', ...(one.length <= width ? [one] : parts.map(x => truncate(x, width))))
  }
  return out.join('\n')
}

// One check in full, for /flow checks <id>.
export function renderCheckDetail(c: Checks, id: string, installed: string | undefined, now: number): string {
  const x = c.items.find(i => i.id === id)
  if (x === undefined) return `${id}: no such check.`
  const state = x.state === 'failed' && x.followUp ? `failed (follow-up ${x.followUp.state === 'started' ? `started by ${x.followUp.manager ?? '?'}` : 'open'})` : x.state
  const needs = x.version === undefined ? 'no version' : x.version + (installed === undefined ? '' : compareVersions(x.version, installed) <= 0 ? ' (installed)' : ' (not installed yet)')
  const lines = [
    `${x.id}: PR #${x.pr}${x.title ? ` ${x.title}` : ''}`,
    `State: ${state}`, `Version: ${needs}`, `Age: ${ago(now - x.createdAt)}`, `Steps: ${x.steps}`,
    ...(x.verifyCommand ? [`Verify command: ${x.verifyCommand}`] : []),
    ...(x.note ? [`Note: ${x.note}`] : []),
    ...(x.closedAt !== undefined ? [`Closed: ${x.state} by ${x.closedBy ?? '?'}, ${ago(now - x.closedAt)} ago`] : []),
  ]
  if (x.state === 'open') lines.push(`Pass: /flow checks pass ${x.id}`, `Fail: /flow checks fail ${x.id} <what you saw>`, `Skip: /flow checks skip ${x.id} <why>`)
  return lines.join('\n')
}

export type CloseResult = { checks: Checks; text: string; failed?: Check[] }

// Closes checks as passed or failed. A closed or unknown id is refused with its state, and nothing is closed
// when any id is refused. `scriptedOnly` (the reviewer) may close only checks that carry a command.
export function closeChecks(
  cur: Checks, ids: string[], how: 'pass' | 'fail' | 'skip', by: string, note: string | undefined, now: number, scriptedOnly = false,
): CloseResult | { error: string } {
  if (ids.length === 0) return { error: 'needs an id (see action "list").' }
  if (how === 'fail' && (note === undefined || note.trim() === '')) return { error: 'a failed check needs a note: what went wrong.' }
  if (how === 'skip' && (note === undefined || note.trim() === '')) return { error: 'a skipped check needs a reason: why it no longer applies.' }
  if (how === 'skip' && scriptedOnly) return { error: 'only main skips a check.' }
  if (how === 'fail' && ids.length > 1) return { error: 'fail one check at a time, each with its own note.' }
  const bad: string[] = []
  for (const id of ids) {
    const c = cur.items.find(x => x.id === id)
    if (c === undefined) bad.push(`${id}: no such check`)
    else if (c.state !== 'open') bad.push(`${id}: already ${c.state}`)
    else if (scriptedOnly && !c.verifyCommand) bad.push(`${id}: has no verify command, only main closes it`)
  }
  if (bad.length) return { error: bad.join('; ') + '.' }
  const hit = new Set(ids)
  const items = cur.items.map(c => !hit.has(c.id) ? c : how === 'skip'
    ? { ...c, state: 'skipped' as const, closedAt: now, closedBy: by, note: note!.trim() }
    : how === 'pass'
    ? { ...c, state: 'passed' as const, closedAt: now, closedBy: by, ...(note?.trim() ? { note: note.trim() } : {}) }
    : { ...c, state: 'failed' as const, closedAt: now, closedBy: by, note: note!.trim(), followUp: { state: 'open' as const } })
  const checks = { ...cur, items }
  const closed = items.filter(c => hit.has(c.id))
  return how === 'skip' ? { checks, text: `Skipped: ${ids.join(', ')}.` } : how === 'pass'
    ? { checks, text: `Passed: ${ids.join(', ')}.` }
    : { checks, failed: closed, text: `${ids[0]} failed. Start a manager on the follow-up: PR #${closed[0]!.pr} (${closed[0]!.title}), steps: ${closed[0]!.steps}. Note: ${closed[0]!.note}. Then call mcp__flow__check {"action":"started","id":"${ids[0]}","manager":"<name>"}.` }
}

// Marks a failed check's follow-up as started by a manager.
export function markStarted(cur: Checks, id: string, manager: string): { checks: Checks; text: string } | { error: string } {
  const c = cur.items.find(x => x.id === id)
  if (c === undefined) return { error: `${id}: no such check.` }
  if (c.state !== 'failed' || c.followUp === undefined) return { error: `${id}: is ${c.state}; only a failed check has a follow-up.` }
  if (c.followUp.state === 'started') return { error: `${id}: follow-up already started by ${c.followUp.manager ?? '?'}.` }
  if (manager.trim() === '') return { error: 'started needs the manager name.' }
  return { checks: { ...cur, items: cur.items.map(x => x.id === id ? { ...x, followUp: { state: 'started' as const, manager: manager.trim() } } : x) }, text: `${id}: follow-up started by ${manager.trim()}.` }
}

// A stored file read back; anything malformed is dropped, unknown fields are not kept.
export function normalizeChecks(raw: unknown): Checks {
  const r = raw as { next?: unknown; items?: unknown; promptedVersion?: unknown } | null
  const str = (v: unknown) => (typeof v === 'string' ? v : undefined)
  const items: Check[] = []
  for (const x of Array.isArray(r?.items) ? r.items : []) {
    const o = x as Record<string, unknown> | null
    if (typeof o !== 'object' || o === null || typeof o.id !== 'string' || typeof o.pr !== 'number' || typeof o.steps !== 'string') continue
    if (o.state !== 'open' && o.state !== 'passed' && o.state !== 'failed' && o.state !== 'skipped') continue
    const fu = o.followUp as { state?: unknown; manager?: unknown } | undefined
    items.push({
      id: o.id, kind: 'check', pr: o.pr, title: str(o.title) ?? '', steps: o.steps,
      ...(str(o.version) !== undefined ? { version: str(o.version) } : {}), ...(str(o.sha) !== undefined ? { sha: str(o.sha) } : {}),
      ...(str(o.verifyCommand) ? { verifyCommand: str(o.verifyCommand) } : {}),
      createdAt: typeof o.createdAt === 'number' ? o.createdAt : 0, state: o.state,
      ...(typeof o.closedAt === 'number' ? { closedAt: o.closedAt } : {}), ...(str(o.closedBy) !== undefined ? { closedBy: str(o.closedBy) } : {}),
      ...(str(o.note) !== undefined ? { note: str(o.note) } : {}),
      ...(o.state === 'failed' ? { followUp: { state: fu?.state === 'started' ? 'started' as const : 'open' as const, ...(str(fu?.manager) !== undefined ? { manager: str(fu?.manager) } : {}) } } : {}),
    })
  }
  const top = Math.max(0, ...items.map(x => Number(/^c(\d+)$/.exec(x.id)?.[1] ?? 0)))
  return { next: Math.max(top + 1, typeof r?.next === 'number' ? r.next : 1), items, ...(typeof r?.promptedVersion === 'string' ? { promptedVersion: r.promptedVersion } : {}) }
}

files.hooks/standing-run.ts:
// Standing answers and guard-test rules, moved out of register.tsx: the rule files, the auto-answer check
// and the rule edits. Everything that touches the engine goes through StandingIo, built by standingIoOf in
// register.tsx (the engine refuses `$` across an import).
import type { LogEvent } from '../types'
import { mergeLayers } from './settings'
import { AUTO, escalation, matchRule, nextRuleId, removeRule, renderRules, renderSeeds, ruleFromQuestion, sameRule, SEEDS, seedIds, seedsToOffer, suggest, validateRule, withDefaults } from './standing'
import type { Resolved, Rule } from './standing'
import { addMapping, parseGuardTests, suggestionQuestion, suggestionsFor } from './guardtests'
import type { GuardMap } from './guardtests'
import { addQuestions, markAnswered, notesOwner, parseChoice } from './inbox'
import type { Inbox, Question } from './inbox'
import { noteKey } from './state'
import { ENV_KIND } from './deploy'
import { PUSH_KIND } from './pushgate'
import { dismissSuggestions, offerNewSuggestions, paneText, pendingSuggestions } from './standing-suggest'

export type StandingIo = {
  locate: () => Promise<string[]>
  readFile: (path: string) => Promise<string | undefined>
  mkdirp: (dir: string) => Promise<unknown>
  writeJson: (path: string, obj: unknown) => Promise<boolean>
  readJson: (path: string) => Promise<unknown>
  stateDir: () => Promise<string | undefined>
  run: (argv: string[]) => Promise<{ exitCode: number; stdout: string; stderr: string }>
  now: () => Promise<number>
  today: () => Promise<string>
  inbox: () => Promise<Inbox>
  withInbox: <T>(fn: (cur: Inbox) => { inbox: Inbox; out: T }) => Promise<T>
  appendNote: (name: string, line: string) => Promise<boolean>
  appendLog: (event: Omit<LogEvent, 'ts'>) => Promise<void>
  best: (what: string, fn: () => Promise<void>) => Promise<void>
}

// Standing answers (standing.ts): the rules of both settings files, read fresh so a rule made a moment ago
// applies to the next ask. A bad rule is dropped by mergeLayers; the others stand. The `conservative` rule
// comes last, on unless conservative_default is false (withDefaults).
export async function loadRules(io: StandingIo, options: Record<string, unknown>): Promise<{ rules: Resolved[]; paths: string[] }> {
  const paths = await io.locate()
  const layers = await Promise.all(paths.map(async path => ({ path, text: path === '' ? undefined : await io.readFile(path) })))
  const merged = mergeLayers(options, layers).raw
  const raw = merged.standing_answers
  return { rules: withDefaults(Array.isArray(raw) ? raw as Resolved[] : [], merged.conservative_default !== false), paths }
}

export type AutoHits = Map<string, { answer: string; rid: string }>

// The standing-answer check shared by ask and pre-flight: a fresh question that a rule matches is marked
// answered in the same write, so it has an id and history. Returns the inbox, the stored questions as they
// are now, and which ones a rule answered.
export function autoAnswer(cur: Inbox, r: ReturnType<typeof addQuestions>, rules: Resolved[], at: number, escalate = false) {
  let next = r.added.some(a => a.fresh) ? r.inbox : cur
  // An escalate rule holds the question for the user: blocking, flagged, never auto-answered.
  if (escalate) {
    for (const { q, fresh } of r.added) {
      const esc = fresh ? escalation(rules, q) : undefined
      if (esc !== undefined) next = { ...next, items: next.items.map(x => (x.id === q.id ? { ...x, blocking: true, escalated: esc.rid, addressee: 'main' } : x)) }
    }
  }
  const hits: AutoHits = new Map()
  for (const { q, fresh } of r.added) {
    const m = fresh ? matchRule(rules, next.items.find(x => x.id === q.id) ?? q) : undefined
    if (m === undefined) continue
    const marked = markAnswered(next, q.id, m.answer, AUTO, at, m.rule.rid)
    if (marked.kind !== 'ok') continue
    next = marked.inbox
    hits.set(q.id, { answer: marked.answer, rid: m.rule.rid })
  }
  const added = r.added.map(a => ({ ...a, q: next.items.find(x => x.id === a.q.id) ?? a.q }))
  return { inbox: next, added, hits }
}

// The decision note and auto-answer log event for each question a rule answered.
export async function recordAutoAnswers(io: StandingIo, added: Array<{ q: Question }>, hits: AutoHits, agent: string): Promise<void> {
  const date = await io.today()
  for (const { q } of added) {
    const hit = hits.get(q.id)
    if (hit === undefined) continue
    await io.appendNote(notesOwner(q), `- ${date} decision: "${q.id} ${q.question}: ${hit.answer}" (standing answer ${hit.rid})`)
    await io.best('logging an auto-answer', () => io.appendLog({ event: 'auto-answer', owner: noteKey(notesOwner(q)), agent, text: `${q.id} rule ${hit.rid}: ${hit.answer}` }))
  }
}

// Rule file changes run one after another: two `always` answers at once must not lose a rule.
let rulesChain: Promise<unknown> = Promise.resolve()
function inRulesChain<T>(fn: () => Promise<T>): Promise<T> {
  const result = rulesChain.then(fn, fn)
  rulesChain = result.catch(() => undefined)
  return result
}

// Read-modify-write one settings file's standing_answers, keeping every other key. fn gets the raw list and
// returns the new one (undefined: no change). A file that is not a JSON object is never rewritten.
async function editRuleFile<T>(io: StandingIo, path: string, fn: (list: unknown[]) => Promise<{ list?: unknown[]; out: T }>): Promise<{ out: T } | { error: string }> {
  let obj: Record<string, unknown> = {}
  const text = await io.readFile(path)
  if (text !== undefined && text.trim() !== '') {
    let data: unknown
    try {
      data = JSON.parse(text)
    } catch {
      return { error: `${path} is not valid JSON; fix it first, flow does not rewrite it.` }
    }
    if (typeof data !== 'object' || data === null || Array.isArray(data)) return { error: `${path} is not a JSON object; flow does not rewrite it.` }
    obj = data as Record<string, unknown>
  }
  let list: unknown = obj.standing_answers
  if (typeof list === 'string') {
    try { list = JSON.parse(list) } catch { return { error: `${path}: "standing_answers" is not valid JSON; fix it first.` } }
  }
  if (list === undefined || list === null) list = []
  if (!Array.isArray(list)) return { error: `${path}: "standing_answers" is not a list; fix it first.` }
  const r = await fn(list)
  if (r.list !== undefined) {
    await io.mkdirp(path.replace(/\/[^/]*$/, ''))
    if (!await io.writeJson(path, { ...obj, standing_answers: r.list })) return { error: `could not write ${path}.` }
  }
  return { out: r.out }
}

export type RuleAdd = { kind: 'added' | 'exists'; id: string } | { kind: 'error'; msg: string }

// Adds a rule to the personal file with a new short id (s1, s2, ..., unique across both files and the inbox).
export function addRule(io: StandingIo, options: Record<string, unknown>, rule: Rule): Promise<RuleAdd> {
  return inRulesChain(async (): Promise<RuleAdd> => {
    const { rules, paths } = await loadRules(io, options)
    const path = paths[1] ?? ''
    if (path === '') return { kind: 'error', msg: 'rules need a repo for the personal file.' }
    // The rule on by default is not in a file: adding the same rule writes it, so it stays when the default is off.
    const dup = rules.find(r => r.source !== 'default' && sameRule(r.rule, rule))
    if (dup !== undefined) return { kind: 'exists', id: dup.rid }
    const used = [...rules.map(r => r.rid), ...(await io.inbox()).items.flatMap(q => (q.rule === undefined ? [] : [q.rule]))]
    const id = nextRuleId(used)
    const r = await editRuleFile(io, path, async list => ({ list: [...list, { id, ...rule }], out: id }))
    return 'error' in r ? { kind: 'error', msg: r.error } : { kind: 'added', id }
  })
}

// Adds a suggested guard mapping to the personal file (never the committed one), keeping every other key and the
// mapping already there. The text tells main to copy it to .claude/flow.json to share it.
export function addGuardTest(io: StandingIo, options: Record<string, unknown>, glob: string, test: string): Promise<string> {
  return inRulesChain(async () => {
    const path = (await io.locate())[1] ?? ''
    if (path === '') return 'No mapping written: guard mappings need a repo for the personal file.'
    let obj: Record<string, unknown> = {}
    const text = await io.readFile(path)
    if (text !== undefined && text.trim() !== '') {
      try { obj = JSON.parse(text) as Record<string, unknown> } catch { return `No mapping written: ${path} is not valid JSON; fix it first, flow does not rewrite it.` }
      if (typeof obj !== 'object' || obj === null || Array.isArray(obj)) return `No mapping written: ${path} is not a JSON object; flow does not rewrite it.`
    }
    const had = obj.guard_tests === undefined ? {} : parseGuardTests(obj.guard_tests)
    if (had === undefined) return `No mapping written: "guard_tests" in ${path} is not an object of globs to test lists; fix it first.`
    const next = addMapping(had, glob, test)
    if ((had[glob] ?? []).includes(test)) return `Already in ${path}: ${JSON.stringify({ [glob]: [test] })}.`
    await io.mkdirp(path.replace(/\/[^/]*$/, ''))
    if (!await io.writeJson(path, { ...obj, guard_tests: next })) return `No mapping written: could not write ${path}.`
    return `Added ${JSON.stringify({ [glob]: [test] })} to ${path} (personal, uncommitted). To share it with the team, copy it into .claude/flow.json under "guard_tests" and commit.`
  })
}

// A PR sent back for failing tests: for each failed test no guard mapping already requires for the PR's files, one
// non-blocking question to main suggests a mapping. Best effort: the send-back itself is already recorded.
export async function suggestGuardTests(io: StandingIo, input: Record<string, unknown>, pr: number, queueName: string, agentId: string | undefined, map: GuardMap): Promise<string> {
  const failed = Array.isArray(input.failed_tests) ? input.failed_tests.filter((t): t is string => typeof t === 'string' && t.trim() !== '') : []
  if (failed.length === 0) return ''
  const diff = await io.run(['gh', 'pr', 'diff', String(pr), '--name-only']).catch(() => undefined)
  if (diff === undefined || diff.exitCode !== 0) return ` No guard suggestion: gh pr diff ${pr} failed${diff === undefined ? '' : `: ${diff.stderr.trim().slice(0, 200)}`}.`
  const files = diff.stdout.split('\n').map(l => l.trim()).filter(Boolean)
  const sugg = suggestionsFor(files, failed, map)
  if (sugg.length === 0) return ''
  const at = await io.now()
  const filed = await io.withInbox(cur => {
    const open = (g: { glob: string; test: string }) => cur.items.some(x => x.state === 'open' && x.guard?.glob === g.glob && x.guard.test === g.test)
    const asked = sugg.filter(x => !open(x)).map(x => suggestionQuestion(pr, x))
    if (asked.length === 0) return { inbox: cur, out: [] as string[] }
    const r = addQuestions(cur, { name: queueName, id: agentId, isManager: false }, 'main', asked, at)
    return { inbox: r.inbox, out: r.added.filter(a => a.fresh).map(a => a.q.id) }
  })
  return filed.length === 0 ? '' : ` Asked main whether to add a guard mapping (${filed.join(', ')}).`
}

// Removes a rule from whichever file holds it. A /config rule cannot be removed from here.
export function dropRule(io: StandingIo, options: Record<string, unknown>, rid: string): Promise<string> {
  return inRulesChain(async () => {
    const { rules, paths } = await loadRules(io, options)
    const hit = rules.find(r => r.rid === rid)
    if (hit === undefined) return `${rid}: no such rule. mcp__flow__standing {"action":"list"} shows them.`
    if (hit.source === 'config') return `${rid}: set in /config, remove it there.`
    if (hit.source === 'default') return `${rid}: on by default, not in a file; turn it off with the setting conservative_default: false (mcp__flow__settings).`
    const path = (hit.source === 'repo' ? paths[0] : paths[1]) ?? ''
    const r = await editRuleFile(io, path, async list => {
      const res = removeRule(list, hit.source, rid)
      return res.removed ? { list: res.list, out: true } : { out: false }
    })
    if ('error' in r) return `${rid}: not removed, ${r.error}`
    if (!r.out) return `${rid}: not found in ${path}.`
    return `${rid}: removed from ${path}${hit.source === 'repo' ? ' (a committed file: the change shows in git status)' : ''}.`
  })
}

// The suggested starting rules, for main's first status call when no rule exists anywhere. The flag is
// written before returning; two calls at once may both show it, none may miss it.
export async function offerSeedsOnce(io: StandingIo, options: Record<string, unknown>): Promise<string[]> {
  const dir = await io.stateDir()
  if (dir === undefined) return []
  const flag = `${dir}/seeds-offered.json`
  if (await io.readJson(flag) !== undefined) return []
  const { rules } = await loadRules(io, options)
  // The rule on by default is not one of your own: the other seeds are still offered beside it.
  const offer = rules.every(r => r.source === 'default') ? seedsToOffer(rules) : []
  if (offer.length === 0) return []
  await io.mkdirp(dir)
  await io.writeJson(flag, { offeredAt: await io.now() })
  return renderSeeds(offer)
}

// Suggested standing rules main has not been offered yet, one line each (standing-suggest.ts), for whichever of
// main's answer and status results comes first.
export async function offerSuggestionsOnce(io: StandingIo, options: Record<string, unknown>): Promise<string[]> {
  const { rules } = await loadRules(io, options)
  return offerNewSuggestions(io, rules)
}

// The Flow pane's suggestion rows: pending ones, each as id and one line of text.
export async function paneSuggestions(io: StandingIo, options: Record<string, unknown>): Promise<Array<{ id: string; text: string }>> {
  const { rules } = await loadRules(io, options)
  return (await pendingSuggestions(io, rules)).map(s => ({ id: s.id, text: paneText(s) }))
}

export async function dismissSuggestionIds(io: StandingIo, options: Record<string, unknown>, ids: string[]): Promise<void> {
  const { rules } = await loadRules(io, options)
  for (const id of ids) await dismissSuggestions(io, rules, id)
}

// An `always` answer: after answering, the answer becomes a rule in the personal file. Only main makes rules.
export async function alwaysRule(
  io: StandingIo, options: Record<string, unknown>, id: string, choice: string, isMain: boolean, before: Question | undefined,
): Promise<string> {
  if (!isMain) return `${id}: no rule made, only main makes standing answers (the answer itself stands).`
  if (before === undefined) return `${id}: no rule made, no such question.`
  if (before.state !== 'open') return `${id}: no rule made, it was already answered.`
  const q = (await io.inbox()).items.find(x => x.id === id)
  if (q === undefined || q.state !== 'answered' || q.answeredBy !== 'main') return `${id}: no rule made, the answer was not recorded.`
  if (q.kind === 'deploy') return `${id}: no rule made, a deploy approval is the user's call every time.`
  if (q.kind === ENV_KIND) return `${id}: no rule made, an env change is the user's call every time.`
  if (q.kind === PUSH_KIND) return `${id}: no rule made, pushing a batch is the user's call every time.`
  if (q.kind === 'reviewer') return `${id}: no rule made, restarting a failing reviewer is the user's call every time.`
  if (parseChoice(q.options, choice).free) return `${id}: no rule made, a free-text answer cannot be a rule; pick one of the options.`
  const rule = ruleFromQuestion(q, q.answer ?? '', await io.today())
  const r = await addRule(io, options, rule)
  if (r.kind === 'error') return `${id}: answered, but no rule made: ${r.msg}`
  const what = rule.topic !== undefined ? `topic ${rule.topic}` : 'this exact question'
  if (r.kind === 'exists') return `${id}: rule ${r.id} already says "${rule.answer}" for ${what}; no duplicate added.`
  return `${id}: rule ${r.id} added: ${what} -> "${rule.answer}"${rule.blocking ? ' (also blocking)' : ''}. Revoke with mcp__flow__standing {"action":"remove","id":"${r.id}"}.`
}

// The standing tool: list, add or remove standing answers. Only main may.
export async function standingTool(io: StandingIo, options: Record<string, unknown>, input: Record<string, unknown>, agentId: string | undefined): Promise<{ result: string }> {
  if (agentId !== undefined) return { result: 'Refused: only main makes or removes standing answers. Ask main in the chat, or answer with the question\'s default.' }
  const action = String(input.action ?? 'list')
  if (action === 'list') {
    const { rules } = await loadRules(io, options)
    const box = await io.inbox()
    return { result: renderRules(rules, box, suggest(box, rules), seedsToOffer(rules)) }
  }
  if (action === 'add' && (input.seed !== undefined || input.seeds !== undefined)) {
    const want = [...new Set([...(typeof input.seed === 'string' ? [input.seed] : []), ...(Array.isArray(input.seeds) ? input.seeds.map(String) : [])].map(s => s.trim()))]
    const bad = want.filter(id => !SEEDS.some(s => s.id === id))
    if (bad.length > 0 || want.length === 0) return { result: `Refused: unknown seed ${bad.map(b => `"${b}"`).join(', ') || '(none given)'}. The ids are ${seedIds().join(', ')}; nothing added.` }
    const date = await io.today()
    const out: string[] = []
    for (const id of want) {
      const seed = SEEDS.find(s => s.id === id)!
      const r = await addRule(io, options, { ...seed.rule, note: `seed ${id}, added ${date}` })
      out.push(r.kind === 'error' ? `${id}: not added: ${r.msg}`
        : r.kind === 'exists' ? `${id}: already there as rule ${r.id}; nothing added.`
          : `${id}: rule ${r.id} added to the personal file. Revoke with mcp__flow__standing {"action":"remove","id":"${r.id}"}.`)
    }
    return { result: out.join('\n') }
  }
  if (action === 'add') {
    const v = validateRule({
      topic: input.topic, match: input.match, answer: input.answer, escalate: input.escalate, blocking: input.blocking, from: input.from, kinds: input.kinds, options: input.options,
      note: `added ${await io.today()} by hand`,
    })
    if ('error' in v) return { result: `Refused: ${v.error}.` }
    const r = await addRule(io, options, v.rule)
    if (r.kind === 'error') return { result: `Not added: ${r.msg}` }
    if (r.kind === 'exists') return { result: `Rule ${r.id} already says that; nothing added.` }
    return { result: `Rule ${r.id} added to the personal file. Revoke with mcp__flow__standing {"action":"remove","id":"${r.id}"}.` }
  }
  if (action === 'dismiss') {
    const id = String(input.id ?? '').trim()
    if (id === '') return { result: 'Refused: dismiss needs the suggestion id (or "all"); it is in the suggestion line.' }
    const { rules } = await loadRules(io, options)
    const done = await dismissSuggestions(io, rules, id)
    return { result: done.length === 0 ? `${id}: no such open suggestion; nothing changed.` : `Dismissed ${done.length} suggestion${done.length === 1 ? '' : 's'}; no rule was added and they are not offered again.` }
  }
  if (action === 'remove') {
    const id = String(input.id ?? '').trim()
    if (id === '') return { result: 'Refused: remove needs the rule id (see action "list").' }
    return { result: await dropRule(io, options, id) }
  }
  return { result: 'Unknown action: use list, add, remove or dismiss.' }
}

files.hooks/decide-eval-run.ts:
// The io half of the main-only `decide_eval` tool (tools.ts): reads the flow state dir, replays it through decide() with
// the session's own settings (so the key stays in /config and never reaches an agent), writes the results next to the state.
import { decide } from './decide'
import type { DecideIo, DecideSettings, Question } from './decide'
import { EXPORT_FILE, FEATURES, formatRoute, formatFeedbackSplit, formatSize, feedbackSplit, loadDatasets, parseExport, reportJson, reportText, routeBaselines, runEval, sizeBaselines } from './decide-eval'
import type { FeatureKey } from './decide-eval'

export const DECIDE_EVAL_FILE = 'decide-eval.json'

export type DecideEvalIo = {
  stateDir: () => Promise<string | undefined>
  readFile: (path: string) => Promise<string | undefined>
  writeFile: (path: string, text: string) => Promise<void>
  decideIo: DecideIo
  now: () => Promise<number>
}

export async function decideEvalTool(io: DecideEvalIo, settings: DecideSettings & { maxContinues: number }, input: Record<string, unknown>, agentId: string | undefined): Promise<string> {
  if (agentId !== undefined) return 'Refused: only main runs decide_eval.'
  const provider = input.provider === 'jev' || input.provider === 'openai' ? input.provider : settings.decisionApi
  const dry = input.dry_run === true
  if (!dry && (provider === undefined || provider === 'off')) return 'Refused: decision_api is off. Set it to jev or openai in /config (with its key), or pass dry_run.'
  const dir = await io.stateDir()
  if (dir === undefined) return 'Refused: not in a git repo, so there is no flow state to replay.'
  const features = Array.isArray(input.features) ? FEATURES.filter(f => (input.features as unknown[]).includes(f)) : FEATURES
  const limit = typeof input.limit === 'number' && input.limit > 0 ? Math.floor(input.limit) : undefined
  // The export of scripts/decide-eval.mjs carries the transcript-derived sets; without it only the state dir is read.
  const exported = parseExport(await io.readFile(`${dir}/${EXPORT_FILE}`))
  const { datasets, units } = exported ?? await loadDatasets({ read: rel => io.readFile(`${dir}/${rel}`), readAbs: io.readFile, maxContinues: settings.maxContinues })
  const ageMin = exported === undefined ? 0 : Math.max(0, Math.round((await io.now() - Date.parse(exported.at)) / 60000))
  const sources = exported
    ? `Source: ${EXPORT_FILE} (export from ${exported.at}, ${ageMin} min old; rerun scripts/decide-eval.mjs --export to refresh).`
    : `Source: the flow state dir only (no ${EXPORT_FILE}; run scripts/decide-eval.mjs --export to add transcript-derived test failures and conflicts, otherwise those come from log.jsonl alone).`
  if (dry) {
    // Size and route also say how many spawns were labelable of how many, and what the key-free sizers score.
    const lines = datasets.filter(d => features.includes(d.key)).map(d => `${d.key}: ${d.records.length} records${d.guard ? ` (+${d.guard.length} must-not-auto-answer)` : ''}. Sample: ${(d.records[0]?.text ?? 'none').slice(0, 300).replace(/\n/g, ' / ')}${d.key === 'size' ? `\n  ${d.notes.join('\n  ')}\n${formatSize(sizeBaselines(d.records))}\n${formatFeedbackSplit(feedbackSplit(d.records))}` : d.key === 'route' ? `\n  ${d.notes.join('\n  ')}\n${formatRoute(routeBaselines(d.records))}` : ''}`)
    return ['Dry run, no network.', ...lines, sources].join('\n')
  }
  const s: DecideSettings = { ...settings, decisionApi: provider as 'jev' | 'openai' }
  // A minimum confidence of 0 keeps the raw confidence of every answer; the thresholds are applied when scoring.
  const ask = (text: string, q: Question) => decide(io.decideIo, s, text, q, undefined, 0)
  const reports = await runEval(ask, datasets, units, { features: features as FeatureKey[], ...(limit !== undefined ? { limit } : {}) })
  const report = { provider: provider as string, at: new Date(await io.now()).toISOString(), features: reports }
  const path = `${dir}/${DECIDE_EVAL_FILE}`
  await io.writeFile(path, reportJson(report))
  return `${reportText(report)}\n\n${sources}\nResults (ids, labels, answers, confidences) written to ${path}.`
}

files.hooks/size-ab.ts:
// The opt-in A/B of Jev sizing (setting size_ab "daily"): which arm a day belongs to, and the report over ledger rows
// tagged with `sizeArm`. The report is read-only and makes no network call (the tool and scripts/size-ab.mjs share it).
import type { Ledger, LedgerEntry, LogEvent } from '../types'
import { baseName, costOf } from './cost'
import { generation } from './routing'

export type SizeArm = 'jev' | 'off'
export const MIN_PACKAGES = 20

// Local epoch day (days since 1970-01-01 in the local calendar), so the 31st and the 1st do not repeat an arm.
// Even epoch day -> arm "jev" (sizes through the decision API), odd -> arm "off" (the Size line alone).
// Only with the decision API on jev: the A/B compares Jev against no Jev, so any other provider has no arm.
export function sizeArmOf(sizeAb: 'off' | 'daily' | undefined, decisionApi: string | undefined, nowMs: number): SizeArm | undefined {
  if (sizeAb !== 'daily' || decisionApi !== 'jev') return undefined
  const day = Math.floor((nowMs - new Date(nowMs).getTimezoneOffset() * 60_000) / 86_400_000)
  return day % 2 === 0 ? 'jev' : 'off'
}

// The sizing function a spawn uses: the off arm gets none, so the decision API is not called (the Size line alone).
export const sizerFor = <T,>(arm: SizeArm | undefined, make: () => T | undefined): T | undefined => (arm === 'off' ? undefined : make())

type Row = Pick<LedgerEntry, 'role' | 'name' | 'manager' | 'branch' | 'spawnModel' | 'models'> & { sizeArm?: string; arm?: LedgerEntry['arm'] }
export type ArmStats = { packages: number; merged: number; usd: number; usdPerMerged?: number; rerun: number; models: Record<string, number> }
export type RoleReport = Record<SizeArm, ArmStats>
export type AbReport = { worker: RoleReport; manager: RoleReport }

const isArm = (v: unknown): v is SizeArm => v === 'jev' || v === 'off'
const usdOf = (r: Row): number => Object.entries(r.models ?? {}).reduce((n, [m, b]) => n + (costOf(m, b) ?? 0), 0)

// Branches of merged pull requests: the reviewer's `done` log event carries the merged PR's branch.
export const mergedBranches = (log: Pick<LogEvent, 'event' | 'branch'>[]): Set<string> =>
  new Set(log.filter(l => l.event === 'done' && l.branch !== undefined).map(l => l.branch!))

// The package a row belongs to: its base name with the -N successors; the arms of a best-of-N group (hooks/bestof.ts)
// are one package (the group), so a group has one first attempt and its arms are not counted as reruns.
const packageOf = (r: Row): string => r.arm !== undefined ? r.arm.group : baseName(r.name)

// A package is a base name with its -N successors, per role, attributed to the arm of its FIRST spawn (lowest
// generation); a package whose first spawn has no arm predates the A/B and is left out. Merged: a worker package has a
// merged branch among its own rows; a manager package has a merged branch among its workers' (rows whose manager is it).
// A manager package's $ is the manager's own rows, its workers are counted in the worker report.
export function sizeAbReport(ledger: Ledger | Record<string, Row>, merged: Set<string>): AbReport {
  const rows = Object.values(ledger as Record<string, Row>).filter(r => typeof r.name === 'string' && (r.role === 'worker' || r.role === 'manager'))
  const empty = (): ArmStats => ({ packages: 0, merged: 0, usd: 0, rerun: 0, models: {} })
  const out: AbReport = { worker: { jev: empty(), off: empty() }, manager: { jev: empty(), off: empty() } }
  for (const role of ['worker', 'manager'] as const) {
    const byBase = new Map<string, Row[]>()
    for (const r of rows.filter(x => x.role === role)) byBase.set(packageOf(r), [...(byBase.get(packageOf(r)) ?? []), r])
    for (const [base, pkg] of byBase) {
      const first = pkg.reduce((a, b) => (generation(b.name) < generation(a.name) ? b : a))
      if (!isArm(first.sizeArm)) continue
      const s = out[role][first.sizeArm]
      s.packages++
      s.usd += pkg.reduce((n, r) => n + usdOf(r), 0)
      if (pkg.some(r => generation(r.name) > 1)) s.rerun++
      for (const r of pkg) if (r.spawnModel !== undefined) s.models[r.spawnModel] = (s.models[r.spawnModel] ?? 0) + 1
      const branches = role === 'worker' ? pkg.map(r => r.branch) : rows.filter(w => w.role === 'worker' && w.manager !== undefined && baseName(w.manager) === base).map(w => w.branch)
      if (branches.some(b => b !== undefined && merged.has(b))) s.merged++
    }
    for (const arm of ['jev', 'off'] as const) { const s = out[role][arm]; if (s.merged > 0) s.usdPerMerged = s.usd / s.merged }
  }
  return out
}

export function formatSizeAb(r: AbReport): string {
  const lines = [
    'Size A/B: arm jev = sized through the decision API (even local epoch day), arm off = the Size line alone (odd day).',
    'A package is a base name with its -N successors, attributed to the arm of its first spawn. Merged = a `done` event in log.jsonl for one of its branches (a manager: any of its workers\' branches). $ is at hooks/cost.ts list prices; a manager package counts the manager\'s own rows only.',
  ]
  const small: string[] = []
  for (const role of ['worker', 'manager'] as const) {
    lines.push('', `${role}s:`)
    for (const arm of ['jev', 'off'] as const) {
      const s = r[role][arm]
      const mix = Object.entries(s.models).sort((a, b) => b[1] - a[1]).map(([m, n]) => `${m} ${n}`).join(', ') || 'none'
      lines.push(`  ${arm}: ${s.packages} packages, ${s.merged} merged, ${s.usdPerMerged === undefined ? 'no $ per merged PR' : `$${s.usdPerMerged.toFixed(2)} per merged PR`} ($${s.usd.toFixed(2)} total), ${s.rerun} needed a -N successor${s.packages > 0 ? ` (${Math.round(100 * s.rerun / s.packages)}%)` : ''}; models: ${mix}`)
    }
    if (r[role].jev.packages < MIN_PACKAGES || r[role].off.packages < MIN_PACKAGES) small.push(role)
  }
  if (small.length > 0) lines.push('', `Too small to conclude (${small.join(' and ')}: fewer than ${MIN_PACKAGES} packages in an arm).`)
  return lines.join('\n')
}

export type SizeAbIo = { stateDir: () => Promise<string | undefined>; readFile: (path: string) => Promise<string | undefined> }

// The main-only size_ab_report tool: reads ledger.json and log.jsonl of the state dir, writes nothing.
export async function sizeAbTool(io: SizeAbIo, agentId: string | undefined): Promise<string> {
  if (agentId !== undefined) return 'Refused: only main runs size_ab_report.'
  const dir = await io.stateDir()
  if (dir === undefined) return 'Refused: not in a git repo, so there is no flow state to read.'
  return reportFrom(await io.readFile(`${dir}/ledger.json`), await io.readFile(`${dir}/log.jsonl`))
}

// The report text from the raw files; shared with scripts/size-ab.mjs.
export function reportFrom(ledgerText: string | undefined, logText: string | undefined): string {
  let ledger: Record<string, Row> = {}
  try { const j = JSON.parse(ledgerText ?? '') as unknown; if (typeof j === 'object' && j !== null) ledger = j as Record<string, Row> } catch { /* none */ }
  const log: LogEvent[] = []
  for (const line of (logText ?? '').split('\n')) { try { const e = JSON.parse(line) as LogEvent; if (typeof e === 'object' && e !== null) log.push(e) } catch { /* torn line */ } }
  return formatSizeAb(sizeAbReport(ledger, mergedBranches(log)))
}

files.hooks/bestof.ts:
// Best-of-N (setting best_of_n): a manager may start 2-3 competing workers ("arms") on one brief. Arms are agent
// workers named `<pkg>-a`, `<pkg>-b`, `<pkg>-c` (a letter, never a number: a trailing -<digits> means successor
// everywhere), each with an `Arm: <letter> of <N>` line in the brief. The manager picks the winner with the arms
// tool; only the winner's PR can be handed over. This file is the pure part: parsing, the spawn check, the
// ledger tag, the pick and the report. The tool's IO is a closure (ArmsIo) built in register.tsx.
import type { Ledger, LedgerEntry, LogEvent } from '../types'
import { baseName, money, totalOf } from './cost'
import { generation } from './routing'
import { mergedBranches } from './size-ab'

export type Arm = NonNullable<LedgerEntry['arm']>
export const ARM_LETTERS = ['a', 'b', 'c']

const ARM_LINE = /^Arm:\s*([a-c])\s+of\s+(\d+)\s*$/im

// The brief's `Arm: b of 3` line. Anything else (another letter, a missing count) is no arm line.
export function parseArm(prompt: string): { id: string; of: number } | undefined {
  const m = ARM_LINE.exec(prompt)
  return m === null ? undefined : { id: m[1]!.toLowerCase(), of: Number(m[2]) }
}

// `csv-export-b` -> group csv-export, letter b. A successor (`csv-export-b-2`) is not an arm name: it stays in its arm.
export function armName(name: string): { group: string; id: string } | undefined {
  const m = /^(.+)-([a-c])$/.exec(name)
  return m === null ? undefined : { group: m[1]!, id: m[2]! }
}

export type SpawnFacts = {
  name: string
  prompt: string
  bestOfN: 'off' | 'brief' | 'auto'
  arms: number
  parentIsManager: boolean
  // Names of the parent's workers at work now (not idle ones; the spawn's own predecessors are left out by the caller).
  liveSiblings: string[]
  // Arm spawns of the same parent that passed this check but are not in the roster yet.
  pending?: number
  maxWorkers: number
  // This arm letter already has ledger rows in the group, or the group was picked: the slug is used up.
  groupUsed?: boolean
}

// The refusal for an arm spawn that breaks the protocol; undefined for a spawn that is no arm or is fine.
export function armSpawnRefusal(f: SpawnFacts): string | undefined {
  const arm = parseArm(f.prompt)
  if (arm === undefined) return undefined
  if (f.bestOfN === 'off') return 'flow: best_of_n is off, so the brief\'s "Arm:" line is refused. Remove the line to start one worker, or ask the user to set best_of_n to brief or auto.'
  if (!f.parentIsManager) return 'flow: only a manager starts best-of-N arms. Start a plain worker (no "Arm:" line) instead.'
  if (arm.of < 2) return `flow: an arm line needs at least 2 arms ("Arm: ${arm.id} of ${arm.of}"). For one worker leave the "Arm:" line out.`
  if (arm.of > f.arms) return `flow: "Arm: ${arm.id} of ${arm.of}" asks for ${arm.of} arms but best_of_n_arms allows ${f.arms}. Start at most ${f.arms}, each "of ${f.arms}" or fewer.`
  if (ARM_LETTERS.indexOf(arm.id) >= arm.of) return `flow: arm ${arm.id} does not exist in a best-of-${arm.of}: the letters are ${ARM_LETTERS.slice(0, arm.of).join(', ')}.`
  // A successor (`<pkg>-a-2`) is named after its arm; the arm itself `<pkg>-a`.
  const own = generation(f.name) >= 2 ? baseName(f.name) : f.name
  const named = armName(own)
  if (named === undefined || named.id !== arm.id) return `flow: arm ${arm.id} must be named "<package>-${arm.id}" (a letter suffix, never a number; got "${f.name}").`
  if (f.groupUsed === true && generation(f.name) < 2) return `flow: group "${named.group}" already has an arm ${arm.id} or a picked winner. Use a new package slug for a new set of arms.`
  const at = f.liveSiblings.length + (f.pending ?? 0)
  if (at + 1 > f.maxWorkers) return `flow: starting ${f.name} would put ${at + 1} workers of yours at work and max_workers is ${f.maxWorkers}. Arms count against it: start fewer arms, or wait for a worker to finish.`
  return undefined
}

// Arm spawns that passed the check and are not in the roster yet, per parent. Agent calls of one message run their
// hooks concurrently, and each reads the roster before any of them is registered, so the count must be taken and the
// slot reserved with no await in between. A reservation expires on its own should the spawn never reach its end.
const reserved = new Map<string, number[]>()
const RESERVE_MS = 60_000
export const pendingOf = (parent: string, now: number): number => (reserved.get(parent) ?? []).filter(u => u > now).length

// Synchronous: the refusal, or a reservation for this arm spawn (call release when the spawn returned or failed).
export function checkAndReserve(f: SpawnFacts, parent: string | undefined, now: number): { deny: string } | { release: () => void } {
  const key = parent ?? ''
  const deny = armSpawnRefusal({ ...f, pending: pendingOf(key, now) })
  if (deny !== undefined) return { deny }
  if (parseArm(f.prompt) === undefined) return { release: () => undefined }
  const until = now + RESERVE_MS
  reserved.set(key, [...(reserved.get(key) ?? []).filter(u => u > now), until])
  return { release: () => { const cur = reserved.get(key) ?? []; const i = cur.indexOf(until); if (i >= 0) reserved.set(key, [...cur.slice(0, i), ...cur.slice(i + 1)]) } }
}

// Whether the arm's group is used up: this letter has a non-successor row, or the group was picked.
export function groupUsed(ledger: Ledger, log: globalThis.Pick<LogEvent, 'event' | 'id' | 'pr' | 'branch' | 'text'>[], group: string, id: string): boolean {
  return pickOf(log, group) !== undefined || Object.values(ledger).some(r => r.role === 'worker' && r.arm?.group === group && r.arm.id === id && generation(r.name) < 2)
}

// The ledger tag for a spawn: an arm from its brief and name, or the successor of an arm (it stays in the arm).
export function armOfSpawn(name: string, prompt: string, ledger: Ledger): Arm | undefined {
  const arm = parseArm(prompt)
  const own = generation(name) >= 2 ? baseName(name) : name
  const named = armName(own)
  if (arm !== undefined && named !== undefined && named.id === arm.id) return { group: named.group, id: arm.id, of: arm.of }
  if (generation(name) < 2) return undefined
  return Object.values(ledger).find(r => r.role === 'worker' && r.arm !== undefined && r.name === own)?.arm
}

// --- groups ---

type ArmRows = { id: string; rows: LedgerEntry[]; branches: string[] }
export type Group = { group: string; manager?: string; of: number; arms: ArmRows[] }

export function groupsOf(ledger: Ledger): Group[] {
  const out = new Map<string, Group>()
  for (const r of Object.values(ledger)) {
    if (r.role !== 'worker' || r.arm === undefined) continue
    const g = out.get(r.arm.group) ?? { group: r.arm.group, of: r.arm.of, arms: [] }
    if (g.manager === undefined && r.manager !== undefined) g.manager = r.manager
    let a = g.arms.find(x => x.id === r.arm!.id)
    if (a === undefined) { a = { id: r.arm.id, rows: [], branches: [] }; g.arms.push(a) }
    a.rows.push(r)
    if (r.branch !== undefined && !a.branches.includes(r.branch)) a.branches.push(r.branch)
    out.set(r.arm.group, g)
  }
  for (const g of out.values()) g.arms.sort((x, y) => x.id.localeCompare(y.id))
  return [...out.values()]
}

// A successor manager (mgr-2) acts for its predecessor's groups.
const sameManager = (a: string | undefined, b: string | undefined): boolean => a !== undefined && b !== undefined && baseName(a) === baseName(b)

// An arm's branch is flow/<pkg>-<letter>; a successor continues on it, or on a numbered sibling of it.
const onBranch = (arm: string, branch: string): boolean => branch === arm || (branch.startsWith(`${arm}-`) && /^\d+$/.test(branch.slice(arm.length + 1)))
const armOfBranch = (g: Group, branch: string): ArmRows | undefined => g.arms.find(a => a.branches.some(b => onBranch(b, branch)))
const groupOfBranch = (ledger: Ledger, branch: string): { g: Group; arm: ArmRows } | undefined => {
  for (const g of groupsOf(ledger)) { const arm = armOfBranch(g, branch); if (arm !== undefined) return { g, arm } }
  return undefined
}

export type ArmPick = { pr: number; branch: string; reason: string }
export function pickOf(log: globalThis.Pick<LogEvent, 'event' | 'id' | 'pr' | 'branch' | 'text'>[], group: string): ArmPick | undefined {
  const e = [...log].reverse().find(l => l.event === 'arm-pick' && l.id === group)
  return e === undefined || e.pr === undefined || e.branch === undefined ? undefined : { pr: e.pr, branch: e.branch, reason: e.text ?? '' }
}

const armCost = (a: ArmRows) => totalOf(a.rows)
const armNameOfRows = (g: Group, a: ArmRows) => `${g.group}-${a.id}`
// Whether a live agent is this arm: the arm itself or its -N successor.
const isArmAgent = (name: string, armName: string): boolean => name === armName || (name.startsWith(`${armName}-`) && /^\d+$/.test(name.slice(armName.length + 1)))

// --- the handover gate and the unhanded filter ---

// Handover of an arm's PR is refused until the manager picked it as the winner.
export function armHandoverRefusal(branch: string, ledger: Ledger, log: LogEvent[]): string | undefined {
  const hit = groupOfBranch(ledger, branch)
  if (hit === undefined) return undefined
  const pick = pickOf(log, hit.g.group)
  if (pick === undefined) return `Refused: ${branch} is arm ${hit.arm.id} of best-of-${hit.g.of} group ${hit.g.group}, and no winner is picked. Review the arms' PRs, call mcp__flow__arms action "pick" (group "${hit.g.group}", pr, reason), then hand over only the winner.`
  if (!onBranch(pick.branch, branch) && !onBranch(branch, pick.branch)) return `Refused: ${branch} lost group ${hit.g.group} to ${pick.branch} (PR #${pick.pr}). Only the picked winner is handed over.`
  return undefined
}

// Branches the "PR nobody handed over" list leaves out: an arm of a group still being decided, or a picked loser.
export function armHidden(ledger: Ledger, log: globalThis.Pick<LogEvent, 'event' | 'id' | 'pr' | 'branch' | 'text'>[], isLiveName: (name: string) => boolean): (branch: string) => boolean {
  return branch => {
    const hit = groupOfBranch(ledger, branch)
    if (hit === undefined) return false
    const pick = pickOf(log, hit.g.group)
    if (pick !== undefined) return !(onBranch(pick.branch, branch) || onBranch(branch, pick.branch))
    return hit.g.arms.some(a => a.rows.some(r => isLiveName(r.name))) || (hit.g.manager !== undefined && isLiveName(hit.g.manager))
  }
}

// --- the arms tool ---

export type Ran = { exitCode: number; stdout: string; stderr: string }
export type ArmsIo = {
  run: (argv: string[]) => Promise<Ran>
  ledger: () => Promise<Ledger>
  log: () => Promise<LogEvent[]>
  appendLog: (event: Omit<LogEvent, 'ts'>) => Promise<void>
  // The caller's name; undefined for the main session.
  callerName: (agentId: string | undefined) => Promise<string | undefined>
  // Names of the agents that are live now.
  liveNames: () => Promise<string[]>
}

const costLine = (g: Group, picked: ArmPick | undefined, merged: Set<string>): string[] => {
  const lines: string[] = []
  let total = 0
  let unknown = false
  let winner: { usd: number } | undefined
  for (const a of g.arms) {
    const t = armCost(a)
    total += t.usd
    unknown ||= t.unknown
    const won = picked !== undefined && a.branches.some(b => onBranch(b, picked.branch))
    if (won) winner = t
    const state = picked === undefined ? 'pending' : won ? (a.branches.some(b => merged.has(b)) ? 'won (merged)' : 'won (not merged)') : 'lost'
    lines.push(`  arm ${a.id}: ${state}, ${money(t.usd, t.unknown)}`)
  }
  const overhead = winner === undefined ? '' : `, winner ${money(winner.usd, unknown)}, overhead ${money(total - winner.usd, unknown)}`
  lines.push(`  group total ${money(total, unknown)}${overhead}`)
  return lines
}

export function armsReport(ledger: Ledger, log: LogEvent[], manager: string | undefined): string {
  const merged = mergedBranches(log)
  const groups = groupsOf(ledger).filter(g => manager === undefined || sameManager(g.manager, manager))
  if (groups.length === 0) return 'No best-of-N arms recorded.'
  const out = ['Best-of-N arms ($ at hooks/cost.ts list prices; overhead = the group\'s cost beyond the winner):']
  for (const g of groups) {
    const p = pickOf(log, g.group)
    out.push(`group ${g.group}${g.manager === undefined ? '' : ` (manager ${g.manager})`}, ${g.of} arms: ${p === undefined ? 'no winner picked yet' : `winner ${p.branch} (PR #${p.pr})`}`, ...costLine(g, p, merged))
  }
  return out.join('\n')
}

export async function armsTool(io: ArmsIo, input: Record<string, unknown>, agentId: string | undefined): Promise<{ result: string }> {
  const caller = await io.callerName(agentId)
  if (agentId !== undefined && caller === undefined) return { result: 'Refused: the arms tool is for the manager that started the arms, or main.' }
  const ledger = await io.ledger()
  const log = await io.log()
  if (input.action === 'report') return { result: armsReport(ledger, log, agentId === undefined ? undefined : caller) }
  if (input.action !== 'pick') return { result: 'Refused: action must be "pick" or "report".' }
  const group = typeof input.group === 'string' ? input.group.trim() : ''
  const pr = Number(input.pr)
  const reason = typeof input.reason === 'string' ? input.reason.trim() : ''
  if (group === '' || !Number.isInteger(pr) || pr <= 0 || reason === '') return { result: 'Refused: pick needs group (the package name without the arm letter), pr (the winner\'s PR number) and reason.' }
  const g = groupsOf(ledger).find(x => x.group === group)
  if (g === undefined) return { result: `Refused: no arms recorded for group "${group}". The group is the package name without the arm letter (csv-export for csv-export-a).` }
  if (agentId !== undefined && !sameManager(g.manager, caller)) return { result: `Refused: group ${group} belongs to manager ${g.manager ?? '?'}; only it (or main) picks.` }
  const view = await io.run(['gh', 'pr', 'view', String(pr), '--json', 'headRefName,state'])
  if (view.exitCode !== 0) return { result: `Refused: gh pr view ${pr} failed: ${view.stderr.trim().slice(0, 300)}` }
  let info: { headRefName: string; state: string }
  try { info = JSON.parse(view.stdout) as { headRefName: string; state: string } } catch { return { result: `Refused: gh pr view ${pr} gave no JSON; try again.` } }
  if (typeof info?.headRefName !== 'string') return { result: `Refused: gh pr view ${pr} gave no branch; try again.` }
  const win = armOfBranch(g, info.headRefName)
  if (win === undefined) return { result: `Refused: PR #${pr} is on ${info.headRefName}, which is no arm of group ${group} (arms: ${g.arms.map(a => a.branches.join('/')).join(', ')}).` }
  const prior = pickOf(log, group)
  if (prior !== undefined && prior.pr !== pr) return { result: `Refused: group ${group} was already picked: PR #${prior.pr} (${prior.branch}). A pick is final; hand over that PR.` }
  if (prior === undefined && info.state !== 'OPEN') return { result: `Refused: PR #${pr} is ${info.state}; the winner must be open.` }
  const loserBranches = g.arms.filter(a => a !== win).flatMap(a => a.branches)
  const list = await io.run(['gh', 'pr', 'list', '--state', 'open', '--limit', '200', '--json', 'number,headRefName'])
  if (list.exitCode !== 0) return { result: `Refused: gh pr list failed, so the other arms' PRs cannot be closed: ${list.stderr.trim().slice(0, 300)}` }
  let listed: { number: number; headRefName: string }[]
  try { listed = JSON.parse(list.stdout || '[]') as typeof listed } catch { return { result: 'Refused: gh pr list gave no JSON, so the other arms\' PRs cannot be closed; try again.' } }
  if (!Array.isArray(listed)) return { result: 'Refused: gh pr list gave an unexpected answer; try again.' }
  const open = listed.filter(p => loserBranches.some(b => onBranch(b, p.headRefName)))
  if (prior === undefined) await io.appendLog({ event: 'arm-pick', owner: caller ?? 'main', id: group, pr, branch: info.headRefName, text: reason })
  const closed: number[] = []
  const failed: string[] = []
  for (const p of open) {
    const r = await io.run(['gh', 'pr', 'close', String(p.number), '--comment', `Closed: arm ${win.id} (PR #${pr}) won best-of-${g.of} group ${group}. Reason: ${reason}`])
    if (r.exitCode === 0) closed.push(p.number)
    else failed.push(`#${p.number} (${r.stderr.trim().slice(0, 120)})`)
  }
  const lost = new Set(log.filter(l => l.event === 'arm-lost' && l.id === group).map(l => l.branch))
  for (const b of loserBranches) if (!lost.has(b)) await io.appendLog({ event: 'arm-lost', owner: caller ?? 'main', id: group, branch: b, pr, text: `lost to PR #${pr}` })
  const live = await io.liveNames()
  const running = g.arms.filter(a => a !== win).map(a => armNameOfRows(g, a)).flatMap(n => live.filter(l => isArmAgent(l, n)))
  const lines = [
    `${prior === undefined ? 'Picked' : 'Already picked'} arm ${win.id} (PR #${pr}) for group ${group}. ${closed.length > 0 ? `Closed the other arms' PRs: ${closed.map(n => `#${n}`).join(', ')}.` : 'No other arm PR was open.'} Remote branches are kept.`,
    ...(failed.length > 0 ? [`Could not close: ${failed.join(', ')}. Close them by hand (gh pr close).`] : []),
    ...(running.length > 0 ? [`Still running: ${running.join(', ')}. Stop each with TaskStop (the plugin cannot), then call mcp__flow__clean.`] : ['No losing arm is running. Hand over only the winner, then call mcp__flow__clean.']),
    'Cost per arm so far:',
    ...costLine(g, { pr, branch: info.headRefName, reason }, mergedBranches(log)),
  ]
  return { result: lines.join('\n') }
}

