import type { AgentRow, Handover, LogEvent } from '../types'
import type { settingsOf } from './settings'
import type { Inbox } from './inbox'
import { expandOk, findItem, isFyi, OVERTURN, renderArchive, renderInbox, renderItem, stillOpen } from './inbox'
import { termWidth } from './table'
import { CHECKS_USAGE, closeChecks, inboxChecksSection, renderCheckDetail, renderChecksTable, resumeChecksLines } from './checks'
import type { Checks } from './checks'
import { renderStatus } from './preflight'
import type { Done, Preflight } from './preflight'
import { resumeInstructions } from './resume'
import type { Gathered, Leftover, OwnerNotes } from './resume'
import { pushLines } from './pushgate-run'
import type { PushAct } from './pushgate-run'
import type { PushState } from './pushgate'
import type { Hold } from './deploy'
import type { QueueWhy } from './reviewer-run'
import { mirror, PANE } from './core'
import { approvePr, rejectPr } from './prcard'
import { LITE_USAGE, liteStartPrompt } from './lite'
import { initCommand } from './init'
import type { Detected } from './init'

type Settings = ReturnType<typeof settingsOf>

// The /flow command. The engine refuses `$` across an import, so register.tsx builds a CommandIo of
// closures over the calls this needs.
export type CommandIo = {
  now: () => Promise<number>
  inbox: () => Promise<Inbox>
  // The noteKeys of agents that are over, to fold their decisions in /flow inbox.
  endedOwners?: () => Promise<Set<string>>
  checks: () => Promise<Checks>
  answerQuestion: (wanted: string, choice: string | null, by: string, options: Record<string, unknown>, user: boolean) => Promise<string>
  withChecks: <T>(fn: (cur: Checks) => { checks: Checks; out: T }) => Promise<T>
  costLines: (prs: { pr: number; branch: string }[]) => Promise<string[]>
  handovers: () => Promise<Record<string, Handover>>
  preflight: () => Promise<Preflight>
  roster: () => Promise<AgentRow[]>
  endedManagers: (state: Preflight, rows: AgentRow[], handovers: Handover[]) => Done
  panes: () => Promise<Array<{ id: string }>>
  close: () => Promise<unknown>
  home: () => Promise<void>
  open: () => Promise<unknown>
  gatherLeftovers: (base: string, resumed: Set<string>) => Promise<Gathered>
  // Ends a reviewer halt or back-off (true when it was halted).
  releaseReviewerHalt: () => Promise<boolean>
  pushState: () => Promise<PushState>
  after: (ms: number, fn: () => void) => void
  submit: (text: string) => Promise<unknown>
  notesPath: (owner: string) => Promise<string | undefined>
  readNotes: (owner: string) => Promise<string>
  sweep: (base: string, apply: boolean, dryHint?: string) => Promise<string>
  putHandover: (pr: string, h: Handover) => Promise<void>
  best: (what: string, fn: () => Promise<void>) => Promise<void>
  saveHandover: (h: Handover) => Promise<void>
  appendLog: (event: Omit<LogEvent, 'ts'>) => Promise<void>
  toast: (text: string) => void
  ensureQueue: (why?: QueueWhy) => Promise<string>
  refresh: () => Promise<unknown>
  pushAct: (act: PushAct, by: string) => Promise<string>
  holdTarget: (name: string, until: Hold['until'], by: string, reason: string | undefined) => Promise<string>
  releaseTarget: (name: string) => Promise<string>
  refreshBehind: () => Promise<void>
  closeReturnedEnv: (h: Handover) => Promise<void>
  settleBatch: () => Promise<void>
  tellManager: (name: string, text: string) => Promise<void>
  // /flow init: detection, the first-run marker and the free demo replay.
  initDetect: (options: Record<string, unknown>) => Promise<Detected>
  initMark: (d: Detected) => Promise<void>
  demoStart: () => Promise<string>
  demoStop: () => Promise<string>
}

export async function flowCommand(
  io: CommandIo, settings: Settings, installed: string | undefined, resumed: Set<string>, options: Record<string, unknown>, args: string | undefined,
  columns?: number,
): Promise<{ text: string; context?: string[] }> {
    // A plugin's $.command.run may leave args out.
    const arg = (args ?? '').trim()
    if (arg === 'inbox' || arg.startsWith('inbox ')) {
      const w = arg.split(/\s+/).slice(1)
      const box = await io.inbox()
      const now = await io.now()
      if (w.length === 1 && /^[qd]\d+$/i.test(w[0]!)) return { text: renderItem(box, w[0]!, now) }
      if (w[0] === 'archive') {
        if (w.length > 2 || (w.length === 2 && w[1] !== 'all')) return { text: 'Usage: /flow inbox archive [all]' }
        return { text: renderArchive(box, now, w[1] === 'all') }
      }
      // `all` is the older spelling of `decisions`: both list every decision.
      if (w.length > 1 || (w.length === 1 && w[0] !== 'all' && w[0] !== 'decisions')) return { text: 'Usage: /flow inbox, /flow inbox decisions (every decision), /flow inbox archive [all] (answered items), /flow inbox <id> (one item in full)' }
      const sec = inboxChecksSection(await io.checks(), installed)
      return { text: [renderInbox(box, now, { all: w.length === 1, width: termWidth(columns), ended: await io.endedOwners?.() }), ...sec].join('\n') }
    }
    if (/^(ok|no|answer)(\s|$)/.test(arg)) {
      const [verb = ''] = arg.split(/\s+/)
      const rest = arg.slice(verb.length).trim()
      const lines: string[] = []
      if (verb === 'ok') {
        const { ids, lines: refused } = expandOk(await io.inbox(), rest === '' ? [] : rest.split(/\s+/))
        lines.push(...refused)
        for (const id of ids) lines.push(await io.answerQuestion(id, null, 'main', options, true))
      } else if (verb === 'no') {
        const m = /^(\S+)(?:\s+([\s\S]+))?$/.exec(rest)
        const q = m === null ? undefined : findItem(await io.inbox(), m[1]!)
        if (m === null) return { text: 'Usage: /flow no <id> [what to do instead]' }
        if (q !== undefined && !isFyi(q)) lines.push(`${q.id}: not a decision; answer a question with /flow answer ${q.id} <choice>.`)
        else lines.push(await io.answerQuestion(m[1]!.toLowerCase(), m[2] ?? OVERTURN, 'main', options, true))
      } else {
        // Two answers pasted on one line split on the literal `/flow answer`; a bare "answer" inside free text stays put.
        const usage = 'Usage: /flow answer <id> <option letter, number or your own words>'
        const pieces = rest.split(/\s+\/flow\s+answer(?:\s+|$)/i).map(p => /^(\S+)\s+([\s\S]+)$/.exec(p.trim()))
        // Parse every piece before answering any, so a malformed line records nothing.
        if (pieces.some(m => m === null)) return { text: pieces.length > 1 ? `One answer per command: a piece has no id or no choice.\n${usage}` : usage }
        for (const m of pieces) lines.push(await io.answerQuestion(m![1]!.toLowerCase(), m![2]!.trim(), 'main', options, true))
      }
      lines.push(stillOpen(await io.inbox()))
      return { text: lines.join('\n') }
    }
    if (arg === 'checks' || arg.startsWith('checks ')) {
      const w = arg.split(/\s+/).slice(1)
      // Ids are matched in any case; only the id words are lowercased, the reason or note keeps its own.
      for (let n = ['pass', 'fail', 'skip'].includes(w[0] ?? '') ? 1 : 0; /^c\d+$/i.test(w[n] ?? ''); n++) w[n] = w[n]!.toLowerCase()
      const t = await io.now()
      if (w.length === 0) return { text: renderChecksTable(await io.checks(), installed, termWidth(columns), t) }
      if (w.length === 1 && !['pass', 'fail', 'skip'].includes(w[0]!)) return { text: renderCheckDetail(await io.checks(), w[0]!, installed, t) }
      if (w[0] === 'pass' && w.length > 1) {
        return { text: await io.withChecks(cur => {
          const r = closeChecks(cur, w.slice(1), 'pass', 'user', undefined, t)
          return 'error' in r ? { checks: cur, out: `Not closed: ${r.error}` } : { checks: r.checks, out: r.text }
        }) }
      }
      if (w[0] === 'fail' && w.length > 1) {
        return { text: await io.withChecks(cur => {
          const r = closeChecks(cur, [w[1]!], 'fail', 'user', w.slice(2).join(' '), t)
          return 'error' in r ? { checks: cur, out: `Not closed: ${r.error}` } : { checks: r.checks, out: `${w[1]} failed; main starts a manager on the follow-up (/flow resume lists it).` }
        }) }
      }
      if (w[0] === 'skip' && w.length > 1) {
        // Leading ids share one reason: the words after the last id-shaped word.
        let n = 1
        while (/^c\d+$/.test(w[n] ?? '')) n++
        return { text: await io.withChecks(cur => {
          const r = closeChecks(cur, w.slice(1, n), 'skip', 'user', w.slice(n).join(' '), t)
          return 'error' in r ? { checks: cur, out: `Not closed: ${r.error}` } : { checks: r.checks, out: r.text }
        }) }
      }
      return { text: CHECKS_USAGE }
    }
    if (arg === 'status') {
      const lines = await io.costLines(Object.values(await io.handovers()))
      return { text: lines.length > 0 ? lines.join('\n') : 'No agent steps counted yet.' }
    }
    if (arg === 'preflight') {
      const state = await io.preflight()
      const done = io.endedManagers(state, await io.roster(), Object.values(await io.handovers()))
      return { text: renderStatus(state, await io.inbox(), done, await io.now(), mirror.preflightWaitMs) }
    }
    // What Esc does in the pane, for when the key is out of reach.
    if (arg === 'home') {
      await io.home()
      return { text: 'Flow pane is on its home view.' }
    }
    if (arg === 'close') {
      if (!(await io.panes()).some(p => p.id === PANE)) return { text: 'The Flow pane is not open.' }
      try {
        await io.close()
      } catch (err) {
        return { text: `The Flow pane stayed open: ${err instanceof Error ? err.message : String(err)}` }
      }
      return { text: 'Flow pane closed.' }
    }
    if (arg === 'lite' || arg.startsWith('lite ')) {
      const task = arg.slice(4).trim()
      if (task === '') return { text: LITE_USAGE }
      // Like /flow resume: a command starts no agent, so a short prompt is submitted once it has returned.
      io.after(0, () => {
        void io.submit(liteStartPrompt(task)).catch(() => undefined)
      })
      return { text: 'Starting a lite manager (manager and workers only, no pre-flight, no reviewer agent).' }
    }
    if (arg === 'resume') {
      const found = await io.gatherLeftovers(settings.base, resumed)
      // A fresh attempt for a reviewer that kept failing to start.
      const halted = await io.releaseReviewerHalt()
      if (halted) void io.ensureQueue().catch(() => undefined)
      // A batch the user has not pushed yet comes first; no manager is started for it.
      const batchLines = pushLines(await io.pushState())
      const waiting = [...(halted ? ['Reviewer halt cleared: a reviewer starts if handovers are pending.'] : []), ...(batchLines.length === 0 ? [] : ['Needs you (a checked batch awaits your push; no manager is started for it):', ...batchLines])]
      if (found.error !== undefined && found.items.length === 0) return { text: [...waiting, found.error].join('\n') }
      const lines = (kind: Leftover['kind'], title: string) => {
        const rows = found.items.filter(i => i.kind === kind)
        return rows.length ? [`${title}:`, ...rows.map(i => `  ${i.line}`)] : []
      }
      const again = found.skipped.length ? ['Already resumed in this session:', ...found.skipped.map(i => `  ${i.line}`)] : []
      const checkLines = resumeChecksLines(await io.checks(), installed)
      if (found.items.length === 0) return { text: [...waiting, ...(checkLines.length || waiting.length ? [] : ['Nothing unfinished.']), ...checkLines, ...again].join('\n') }
      const text = [
        ...waiting,
        ...checkLines,
        ...(found.error !== undefined ? [found.error] : []),
        ...lines('pr', 'Open PRs'), ...lines('branch', 'Branches without a PR'), ...lines('worktree', 'Worktrees with leftover work'), ...again,
      ].join('\n')
      for (const i of found.items) resumed.add(i.key)
      // The instructions ride as hidden `context`. A command's context alone starts no turn and the
      // host refuses `prompt.submit` from inside a command.run hook, so a short prompt is submitted
      // once the command has returned, to make the main session act on it.
      io.after(0, () => {
        void io.submit('Carry out the /flow resume instructions: start the managers.').catch(() => undefined)
      })
      const notes = new Map<string, OwnerNotes>()
      for (const o of new Set(found.items.map(i => i.owner))) {
        const path = o === undefined ? undefined : await io.notesPath(o)
        if (o !== undefined && path !== undefined) notes.set(o, { path, text: await io.readNotes(o) })
      }
      return { text, context: [resumeInstructions(found.items, settings.maxManagers, notes)] }
    }
    const words = arg.split(/\s+/)
    if (words[0] === 'init') {
      return initCommand({ detect: () => io.initDetect(options), markDone: io.initMark, demoStart: io.demoStart, demoStop: io.demoStop, after: io.after, submit: io.submit }, words.slice(1))
    }
    if (words[0] === 'clean' && words.slice(1).every(w => w === '--yes')) {
      // A person's command: --yes removes whatever the cleanup setting says.
      return { text: await io.sweep(settings.base, words.length > 1, 'Run /flow clean --yes to remove them.') }
    }
    if (words[0] === 'approve') {
      // Only a person's command approves; no tool does.
      const n = Number(words[1])
      if (words.length !== 2 || !Number.isInteger(n) || n <= 0) return { text: 'Usage: /flow approve <pr>' }
      return { text: await approvePr(io, n) }
    }
    if (words[0] === 'reject' || words[0] === 'drop') {
      // Only a person's command turns a handover down; the GitHub PR and branch are left alone.
      const n = Number((words[1] ?? '').replace(/^#/, ''))
      if (!Number.isInteger(n) || n <= 0) return { text: 'Usage: /flow reject <pr> [reason] (alias: /flow drop)' }
      return { text: await rejectPr(io, n, words.slice(2).join(' ')) }
    }
    if (words[0] === 'push') {
      // Only a person's command releases a ready batch (or main, on the user's word, with the push tool).
      const usage = 'Usage: /flow push (push the ready batch), /flow push back <pr> (send one PR back), /flow push drop (return them all)'
      if (words.length === 1) return { text: await io.pushAct({ kind: 'push' }, 'user') }
      if (words[1] === 'drop' && words.length === 2) return { text: await io.pushAct({ kind: 'drop' }, 'user') }
      const n = Number((words[2] ?? '').replace(/^#/, ''))
      if (words[1] === 'back' && words.length === 3 && Number.isInteger(n) && n > 0) return { text: await io.pushAct({ kind: 'back', pr: n }, 'user') }
      return { text: usage }
    }
    if (words[0] === 'hold' || words[0] === 'release') {
      // A person's command, the same as the deploy tool is for main.
      const [, name, until] = words
      if (name === undefined || words.length > (words[0] === 'hold' ? 3 : 2) || (until !== undefined && until !== 'batch' && until !== 'released')) {
        return { text: words[0] === 'hold' ? 'Usage: /flow hold <target> [batch|released] (default released)' : 'Usage: /flow release <target>' }
      }
      const text = words[0] === 'hold' ? await io.holdTarget(name, until === 'batch' ? 'batch' : 'released', 'user', undefined) : await io.releaseTarget(name)
      await io.refreshBehind()
      return { text }
    }
    if (arg !== '') return { text: `Unknown argument "${arg}". /flow opens the Flow pane, /flow inbox lists the open questions and the decisions agents made, /flow ok keeps decisions, /flow no <id> undoes one, /flow answer <id> <choice> answers a question, /flow checks lists the after-deploy checks that need a person, /flow preflight shows the pre-flight round, /flow close closes it, /flow resume picks up unfinished work, /flow approve <pr> lets the reviewer merge a PR that awaits your approval, /flow reject <pr> [reason] (or /flow drop) turns a handover down, /flow push starts the push of the batch the reviewer checked (/flow push back <pr> sends one PR back, /flow push drop returns them all), /flow hold <target> [batch|released] keeps a deploy target from deploying and /flow release <target> lets it, /flow clean lists leftover worktrees and branches (/flow clean --yes removes them), /flow init walks you through flow, runs a demo and sets your settings.` }
    await io.open()
    return { text: 'Flow pane opened.' }
}

files.hooks/meter.ts:
import type { AgentRow } from '../types'
import type { WarnSettings } from './settings'

// Pure meter and label helpers for the agent rows: no engine, no atoms.

// Running time as the native subagent row has it: 12s, 1m 43s, 1h 5m.
export function elapsed(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000))
  if (s < 60) return `${s}s`
  const m = Math.floor(s / 60)
  return m < 60 ? `${m}m ${s % 60}s` : `${Math.floor(m / 60)}h ${m % 60}m`
}

// "↓ 84.0k tokens": the context the agent has taken in, one decimal like the native row.
export function tokensDown(n: number): string {
  return `↓ ${n >= 1_000_000 ? `${(n / 1_000_000).toFixed(1)}M` : n >= 1000 ? `${(n / 1000).toFixed(1)}k` : n} tokens`
}

export function labelOf(a: AgentRow): string {
  return a.name ?? a.description ?? a.id.slice(0, 8)
}

export const DEFAULT_WINDOW = 200_000
export const METER_CELLS = 12
export const CARD_ROWS = 5
export const DANGER_PERCENT = 90

export const LARGE_WINDOW = 1_000_000

// The model id with what differs between the spellings of one model dropped: `[1m]`, a date suffix, `-latest`.
// `e.model` is the id the engine resolved (it may carry `[1m]`); `usage.model` is the id the API reports.
export function modelKey(model: string): string {
  return model.toLowerCase().replace(/\[1m\]/g, '').replace(/-latest$/, '').replace(/-\d{8}$/, '')
}

// A subagent reports no window of its own: borrow the main session's when it runs the same model
// (compared by modelKey), else 200k, or 1M for a `[1m]` model id. Tokens past the assumed window
// prove the window is the 1M one, so a guess is never shown past 100%.
// `spawned` is the window the agent was started with (see the agent.spawn hook); it wins over the guess.
export function windowOf(model: string, mainModel: string | undefined, mainWindow: number | undefined, tokens = 0, spawned?: number): number {
  const window = spawned !== undefined ? spawned : mainWindow !== undefined && mainModel !== undefined && modelKey(model) === modelKey(mainModel) ? mainWindow
    : model.includes('[1m]') ? LARGE_WINDOW : DEFAULT_WINDOW
  return tokens > window ? Math.max(window, LARGE_WINDOW) : window
}


// The percent in force: a 1M window has its own, so the 200k percent never applies to it.
export function windowPercent(s: WarnSettings, window: number): number {
  return window >= LARGE_WINDOW ? s.contextWarn1m : s.contextWarn
}

// The trigger: the percent of the window, capped by the token setting when that is set.
export function thresholdOf(s: WarnSettings, window: number): number {
  const byPercent = Math.round(window * windowPercent(s, window) / 100)
  return s.contextWarnTokens > 0 ? Math.min(s.contextWarnTokens, byPercent) : byPercent
}

// The same threshold as a percent of the window, for the meter's marker and colour.
export function warnPercent(s: WarnSettings, window: number): number {
  return Math.min(100, Math.max(1, Math.round(thresholdOf(s, window) / window * 100)))
}

// What the threshold is called in a message: "40%" or "100k tokens".
export function limitLabel(s: WarnSettings, window: number): string {
  return s.contextWarnTokens > 0 && s.contextWarnTokens < Math.round(window * windowPercent(s, window) / 100)
    ? `${tokensLabel(s.contextWarnTokens)} tokens` : `${windowPercent(s, window)}%`
}

// The threshold in tokens for the meter, only when the token limit is the one in force.
export function limitTokens(s: WarnSettings, window: number): string | undefined {
  return limitLabel(s, window).endsWith('tokens') ? tokensLabel(s.contextWarnTokens) : undefined
}

// The line an agent past the threshold reads. A manager keeps going until its workers are done.
export function wrapUpText(role: string, percent: number, limit: string): string {
  const handoff = 'follow the Handoff section of your instructions now: commit WIP, push, update the draft PR\'s ## Handoff note, end with HANDOFF: <branch>.'
  return role === 'manager'
    ? `flow: WRAP UP: your context is at ${percent}% (past the ${limit} limit). Start no new work; once none of your workers is running, ${handoff}`
    : `flow: WRAP UP: your context is at ${percent}% (past the ${limit} limit). Stop new work, ${handoff}`
}

export function tokensLabel(n: number): string {
  if (n >= 1_000_000) return `${+(n / 1_000_000).toFixed(1)}M`
  return n >= 1000 ? `${Math.round(n / 1000)}k` : String(n)
}

// The bar with a marker cell at the warn threshold, so how close an agent is stays readable.
export function cells(percent: number, warn: number): { ch: string; kind: 'mark' | 'fill' | 'empty' }[] {
  const filled = Math.round(Math.min(100, percent) / 100 * METER_CELLS)
  const mark = Math.min(METER_CELLS - 1, Math.floor(warn / 100 * METER_CELLS))
  return Array.from({ length: METER_CELLS }, (_, i) =>
    i === mark ? { ch: '│', kind: 'mark' } : i < filled ? { ch: '█', kind: 'fill' } : { ch: '░', kind: 'empty' })
}

export function meterColor(percent: number, warn: number): string | undefined {
  return percent >= DANGER_PERCENT && percent >= warn ? 'error' : percent >= warn ? 'warning' : undefined
}

