// Redraw pacing for the Flow pane. The engine redraws a render hook whenever an atom it read changes (at most
// ten a second), and every draw rebuilds the whole tree, so ten streaming agents made the pane redraw as fast as
// the engine allowed. A draw here reads one snapshot of the atoms (the engine still subscribes the instance to
// each), then decides: a person's action (props, focus, selection, scrolling, the inbox) draws at once; a
// background change (activity, ledger, roster, the clock) draws at most every BG_MS, the newest state always
// drawn by a trailing redraw; a change that alters nothing drawn returns the last tree.
export const BG_MS = 250
// Token counts move on every step but a changing number needs no more than this to look live.
export const TOKENS_MS = 1000
export const USAGE_TTL_MS = 1000

const sameList = (a: readonly unknown[], b: readonly unknown[]) => a.length === b.length && a.every((v, i) => Object.is(v, b[i]))

// Activity maps equal apart from usage.tokens, which only the slower window waits for.
export function sameBeyondTokens(a: Record<string, unknown>, b: Record<string, unknown>): boolean {
  if (a === b) return true
  const ka = Object.keys(a)
  if (ka.length !== Object.keys(b).length) return false
  return ka.every(k => {
    const x = a[k] as Record<string, unknown> | undefined
    const y = b[k] as Record<string, unknown> | undefined
    if (x === y) return true
    if (x === undefined || y === undefined) return false
    const { usage: ux, ...rx } = x as { usage?: Record<string, unknown> }
    const { usage: uy, ...ry } = y as { usage?: Record<string, unknown> }
    if (JSON.stringify(rx) !== JSON.stringify(ry)) return false
    if (ux === undefined || uy === undefined) return ux === uy
    return JSON.stringify({ ...ux, tokens: 0 }) === JSON.stringify({ ...uy, tokens: 0 })
  })
}

// What a draw's decision looks at. `user` and `bg` are lists of atom values compared by identity; `activity` is the
// activity map; `props` is the event's props and viewport as text.
export type DrawKeys = { props: string; user: readonly unknown[]; bg: readonly unknown[]; activity: Record<string, unknown> }

export type Drawn<T> = { tree: T; keys: DrawKeys; at: number }

export type Gate<T> = {
  // Draws (calling `draw`) or returns the last tree; `later(ms, fired)` asks for a redraw that long from now and calls `fired` when it comes.
  frame: (keys: DrawKeys, draw: () => Promise<T>, later: (ms: number, fired: () => void) => void) => Promise<T>
  last: () => Drawn<T> | undefined
}

export function createGate<T>(clock: () => number = Date.now): Gate<T> {
  let last: Drawn<T> | undefined
  let waiting = false
  const drawNow = async (keys: DrawKeys, draw: () => Promise<T>) => {
    const tree = await draw()
    last = { tree, keys, at: clock() }
    return tree
  }
  return {
    last: () => last,
    async frame(keys, draw, later) {
      if (last === undefined || last.keys.props !== keys.props || !sameList(last.keys.user, keys.user)) return drawNow(keys, draw)
      const shapeMoved = !sameList(last.keys.bg, keys.bg) || !sameBeyondTokens(last.keys.activity, keys.activity)
      if (!shapeMoved && (last.keys.activity === keys.activity || JSON.stringify(last.keys.activity) === JSON.stringify(keys.activity))) return last.tree
      const wait = (shapeMoved ? BG_MS : TOKENS_MS) - (clock() - last.at)
      if (wait <= 0) return drawNow(keys, draw)
      // One pending timer covers every change inside the window; its redraw finds the newest state.
      if (!waiting) {
        waiting = true
        later(wait, () => { waiting = false })
      }
      return last.tree
    },
  }
}

// A value fetched at most once per ttl; a clock that went backwards fetches again.
export function ttlCache<T>(ttl: number, clock: () => number = Date.now): (fetch: () => Promise<T>) => Promise<T> {
  let seen: { at: number; value: T } | undefined
  return async fetch => {
    const t = clock()
    if (seen === undefined || t - seen.at >= ttl || t < seen.at) seen = { at: t, value: await fetch() }
    return seen.value
  }
}

files.hooks/graph.ts:
// The graph view's layout, pure: no `$` calls, so it is tested on its own. A level (the managers
// of the session, or the workers of one manager) becomes text lines; the Pane colors the
// segments that carry a `node` by that node's state and moves a focus over them.
import type { DagNode } from '../types'
import { agentFor, layers } from './dag'
import type { Graph } from './dag'

export type GNode = {
  id: string
  label: string
  // A DagState, or an agent status for an agent that is not in the plan.
  state: string
  after: string[]
  agentId?: string
  badge?: string
}

export type Seg = { text: string; node?: string; dim?: boolean }
export type Layout = { mode: 'layers' | 'list'; lines: Seg[][]; at: Record<string, number>; order: string[] }

type AgentLike = { id: string; name?: string; status: string; type?: string }

// Columns are joined by this many characters: stub, trunk, arrow.
const GAP = 3
const MIN_WIDTH = 40
const MIN_COL = 10

// The nodes of one level: the plan's nodes, then the agents of that level the plan does not know.
// `children` counts the collapsed workers behind an agent id.
export function graphNodes(graph: Graph | undefined, agents: AgentLike[], opts: { children?: Record<string, number> } = {}): GNode[] {
  const plan = graph ?? {}
  const badgeOf = (agentId: string | undefined) => {
    const n = agentId ? opts.children?.[agentId] : undefined
    return n ? `+${n} workers` : undefined
  }
  const out: GNode[] = []
  for (const n of Object.values(plan)) {
    const agent = n.state === 'waiting' || n.state === 'ready' ? undefined : agentFor(n.id, agents.map(a => ({ ...a, name: a.name ?? a.id })))
    const found = agent && agents.find(a => a.id === agent.id)
    out.push({ id: n.id, label: n.id, state: n.state, after: [...n.after], ...(found ? { agentId: found.id } : {}), ...(badgeOf(found?.id) ? { badge: badgeOf(found?.id) } : {}) })
  }
  const taken = new Set(out.map(n => n.id))
  // An agent belongs to the plan when it is a node's agent or one of its handoff continuations.
  const inPlan = (name: string) => !!plan[name] || !!plan[name.replace(/-\d+$/, '')]
  for (const a of agents) {
    const name = a.name ?? a.id
    if (inPlan(name) || taken.has(a.id)) continue
    taken.add(a.id)
    out.push({ id: a.id, label: name, state: a.status, after: [], agentId: a.id, ...(badgeOf(a.id) ? { badge: badgeOf(a.id) } : {}) })
  }
  return out
}

const trunc = (s: string, n: number) => (s.length <= n ? s : n <= 1 ? '…'.slice(0, Math.max(n, 0)) : s.slice(0, n - 1) + '…')

// Box characters by which sides are connected.
const U = 1
const D = 2
const L = 4
const R = 8
const BOX: Record<number, string> = {
  [U]: '╵', [D]: '╷', [L]: '╴', [R]: '╶',
  [U | D]: '│', [L | R]: '─', [D | R]: '┌', [D | L]: '┐', [U | R]: '└', [U | L]: '┘',
  [U | D | R]: '├', [U | D | L]: '┤', [L | R | D]: '┬', [L | R | U]: '┴', [U | D | L | R]: '┼',
}

export function layoutGraph(nodes: GNode[], width: number): Layout {
  const seen = new Set<string>()
  const uniq = nodes.filter(n => !seen.has(n.id) && !!seen.add(n.id))
  // A dependency that is not in this level counts as no dependency: the node is a root.
  const deps: Record<string, string[]> = {}
  const g: Graph = {}
  for (const n of uniq) {
    deps[n.id] = n.after.filter(d => seen.has(d) && d !== n.id)
    g[n.id] = { id: n.id, title: n.label, after: deps[n.id], until: 'merged', state: 'waiting' } as unknown as DagNode
  }
  if (!uniq.length) return { mode: 'layers', lines: [], at: {}, order: [] }
  const depth = layers(g)
  const count = Math.max(...Object.values(depth)) + 1
  const byLayer: GNode[][] = Array.from({ length: count }, () => [])
  for (const n of uniq) byLayer[depth[n.id] ?? 0]?.push(n)
  const avail = Math.floor((width - GAP * (count - 1)) / count)
  if (width < MIN_WIDTH || avail < MIN_COL) return listLayout(byLayer, deps, uniq)
  return layerLayout(byLayer, deps, depth, avail, width)
}

function listLayout(byLayer: GNode[][], deps: Record<string, string[]>, all: GNode[]): Layout {
  const byId = Object.fromEntries(all.map(n => [n.id, n]))
  const lines: Seg[][] = []
  const at: Record<string, number> = {}
  const order: string[] = []
  byLayer.forEach((level, d) => {
    lines.push([{ text: `── ${d} ──`, dim: true }])
    for (const n of level) {
      at[n.id] = lines.length
      order.push(n.id)
      const line: Seg[] = [{ text: n.label, node: n.id }]
      if (n.badge) line.push({ text: ` ${n.badge}`, dim: true })
      const after = deps[n.id] ?? []
      if (after.length) line.push({ text: `  after: ${after.map(x => byId[x]?.label ?? x).join(', ')}`, dim: true })
      lines.push(line)
    }
  })
  return { mode: 'list', lines, at, order }
}

function layerLayout(byLayer: GNode[][], deps: Record<string, string[]>, depth: Record<string, number>, avail: number, width: number): Layout {
  const all = byLayer.flat()
  const byId = Object.fromEntries(all.map(n => [n.id, n]))
  const count = byLayer.length

  // Column widths: as wide as the longest label of the layer, never wider than the share of the pane.
  const full = (n: GNode) => n.label.length + (n.badge ? 1 + n.badge.length : 0)
  const colw = byLayer.map(level => Math.min(avail, Math.max(...level.map(full))))
  const colx: number[] = []
  colw.reduce((x, w, i) => ((colx[i] = x), x + w + GAP), 0)
  // Every id here comes from `all`, so the fallbacks only satisfy the index checks.
  const depthOf = (id: string) => depth[id] ?? 0
  const colwOf = (id: string) => colw[depthOf(id)] ?? 0
  const colxOf = (layer: number) => colx[layer] ?? 0

  // Rows: a node sits on the row of its highest dependency when that is free, so a chain is a
  // straight line; a layer's nodes never share a row.
  const row: Record<string, number> = {}
  byLayer.forEach(level => {
    const want = level.map((n, i) => {
      const ds = deps[n.id] ?? []
      return { n, i, w: ds.length ? Math.min(...ds.map(d => row[d] ?? 0)) : 0 }
    })
    want.sort((a, b) => a.w - b.w || a.i - b.i)
    let last = -1
    for (const { n, w } of want) row[n.id] = last = Math.max(w, last + 1)
  })
  const rowOf = (id: string) => row[id] ?? 0
  const rows = Math.max(...all.map(n => rowOf(n.id))) + 1

  // Edges between neighbouring layers share a trunk in the gap. Two edges may share it only when
  // they meet at one node (a fan-out or fan-in) or their row ranges do not touch; any other edge
  // is left out and named in an `after:` note under its node.
  const drawn: Array<Array<{ p: string; c: string; lo: number; hi: number }>> = Array.from({ length: count }, () => [])
  const rejected: Record<string, string[]> = {}
  const candidates: Array<{ p: string; c: string; gap: number }> = []
  for (const n of all) {
    for (const d of deps[n.id] ?? []) {
      if (depthOf(d) === depthOf(n.id) - 1) candidates.push({ p: d, c: n.id, gap: depthOf(d) })
      else (rejected[n.id] ??= []).push(d)
    }
  }
  const span = (e: { p: string; c: string }): [number, number] => [Math.min(rowOf(e.p), rowOf(e.c)), Math.max(rowOf(e.p), rowOf(e.c))]
  // Straight and short edges first: they are the ones that stay legible.
  candidates.sort((a, b) => Math.abs(rowOf(a.p) - rowOf(a.c)) - Math.abs(rowOf(b.p) - rowOf(b.c)))
  for (const e of candidates) {
    const [lo, hi] = span(e)
    const edges = drawn[e.gap] ?? []
    const clash = edges.some(o => o.p !== e.p && o.c !== e.c && o.lo <= hi && lo <= o.hi)
    if (clash) (rejected[e.c] ??= []).push(e.p)
    else edges.push({ p: e.p, c: e.c, lo, hi })
  }

  // One line per row, plus a note line under a row when one of its nodes has a rejected edge.
  const noted = new Set<number>()
  for (const id of Object.keys(rejected)) noted.add(rowOf(id))
  const rowLine: number[] = []
  let total = 0
  for (let r = 0; r < rows; r++) {
    rowLine[r] = total
    total += noted.has(r) ? 2 : 1
  }

  type Item = { col: number; text: string; node?: string; dim?: boolean }
  const items: Item[][] = Array.from({ length: total }, () => [])
  const masks: Array<Record<number, number>> = Array.from({ length: total }, () => ({}))
  const arrows: Array<Set<number>> = Array.from({ length: total }, () => new Set())
  const lineOf = (id: string) => rowLine[rowOf(id)] ?? 0
  const add = (line: number, col: number, m: number) => {
    const mask = masks[line]
    if (mask) mask[col] = (mask[col] ?? 0) | m
  }

  const fitted: Record<string, { label: string; badge?: string }> = {}
  for (const n of all) {
    const w = colwOf(n.id)
    const room = n.badge ? w - 1 - n.badge.length : w
    const fit = n.badge && room >= 2 ? { label: trunc(n.label, room), badge: n.badge } : { label: trunc(n.label, w) }
    fitted[n.id] = fit
    const its = items[lineOf(n.id)]
    its?.push({ col: colxOf(depthOf(n.id)), text: fit.label, node: n.id })
    if (fit.badge) its?.push({ col: colxOf(depthOf(n.id)) + fit.label.length + 1, text: fit.badge, dim: true })
  }
  const usedBy = (id: string) => {
    const f = fitted[id]
    return f ? f.label.length + (f.badge ? 1 + f.badge.length : 0) : 0
  }

  drawn.forEach((edges, gap) => {
    const x0 = colxOf(gap) + (colw[gap] ?? 0)
    for (const e of edges) {
      const lp = lineOf(e.p)
      const lc = lineOf(e.c)
      const used = usedBy(e.p)
      // Bridge the blank between a short label and the gap.
      for (let x = colxOf(gap) + used + 1; x < x0; x++) add(lp, x, L | R)
      add(lp, x0, L | R)
      add(lc, x0 + 2, L | R)
      arrows[lc]?.add(x0 + 2)
      if (lp === lc) {
        add(lp, x0 + 1, L | R)
        continue
      }
      const down = lc > lp
      add(lp, x0 + 1, L | (down ? D : U))
      add(lc, x0 + 1, R | (down ? U : D))
      for (let l = Math.min(lp, lc) + 1; l < Math.max(lp, lc); l++) add(l, x0 + 1, U | D)
    }
  })

  for (const id of Object.keys(rejected)) {
    const line = lineOf(id) + 1
    const text = `after: ${(rejected[id] ?? []).map(d => byId[d]?.label ?? d).join(', ')}`
    items[line]?.push({ col: colxOf(depthOf(id)), text, dim: true })
  }

  const lines: Seg[][] = items.map((its, line) => {
    const mask = masks[line] ?? {}
    // A note may run on into the gaps and the next column until something else is there.
    its.sort((a, b) => a.col - b.col)
    its.forEach((it, i) => {
      if (it.node || !it.text.startsWith('after: ')) return
      const owner = Object.keys(rejected).find(id => lineOf(id) + 1 === line && colxOf(depthOf(id)) === it.col) ?? ''
      const home = colwOf(owner)
      const limit = (its[i + 1]?.col ?? Infinity) - 1
      let end = Math.min(it.col + it.text.length, limit, width)
      for (let x = it.col + home; x < end; x++) {
        if (mask[x]) {
          end = x - 1
          break
        }
      }
      it.text = trunc(it.text, Math.max(end - it.col, 1))
    })
    for (const x of Object.keys(mask)) {
      const col = Number(x)
      const ch = arrows[line]?.has(col) ? '→' : BOX[mask[col] ?? 0] ?? '┼'
      its.push({ col, text: ch, dim: true })
    }
    its.sort((a, b) => a.col - b.col)
    const segs: Seg[] = []
    let cursor = 0
    for (const it of its) {
      if (it.col > cursor) segs.push({ text: ' '.repeat(it.col - cursor) })
      const last = segs[segs.length - 1]
      // Edge characters of one run become one segment.
      if (it.dim && !it.node && it.col === cursor && last?.dim && !last.node && /^[─│┌┐└┘├┤┬┴┼╵╷╴╶→]+$/.test(it.text + last.text)) last.text += it.text
      else segs.push({ text: it.text, ...(it.node ? { node: it.node } : {}), ...(it.dim ? { dim: true } : {}) })
      cursor = it.col + it.text.length
    }
    return segs
  })

  const at: Record<string, number> = {}
  const order: string[] = []
  byLayer.forEach(level => {
    for (const n of [...level].sort((a, b) => rowOf(a.id) - rowOf(b.id))) {
      at[n.id] = lineOf(n.id)
      order.push(n.id)
    }
  })
  return { mode: 'layers', lines, at, order }
}

// Where the focus goes. j/k walk `order` (layer by layer, wrapping at the ends); h goes to the
// first dependency, l to the first dependent; a key with nowhere to go keeps the focus.
export function moveFocus(layout: Layout, nodes: GNode[], cur: string | undefined, key: 'h' | 'j' | 'k' | 'l'): string | undefined {
  const { order } = layout
  if (!order.length) return undefined
  if (cur === undefined || !order.includes(cur)) return order[0]
  const byId = Object.fromEntries(nodes.map(n => [n.id, n]))
  const i = order.indexOf(cur)
  if (key === 'j') return order[(i + 1) % order.length]
  if (key === 'k') return order[(i - 1 + order.length) % order.length]
  if (key === 'h') return (byId[cur]?.after ?? []).find(d => order.includes(d)) ?? cur
  return order.find(id => byId[id]?.after.includes(cur)) ?? cur
}

files.hooks/testguard.ts:
import type { AgentRow, TestSlots } from '../types'
import { heldBy, reapSlots } from './slots'
import { reapTypecheck } from './typecheck-slots'
import { MAX_DEPTH, innerScript, parse, resolve } from './guards'

// The test-slot guard's matcher: is a Bash command a whole-suite run? Pure, so it is testable
// without the engine. A segment matches a pattern by token prefix (the pattern's tokens, then
// anything). What follows decides: no file arguments, a glob, a directory or more than
// MAX_FILES explicit files is the whole suite; one to MAX_FILES explicit files run freely.
const MAX_FILES = 5
const GLOB = /[*?[]/
// A path whose last part has no file extension (`.`, `tests`, `/tmp/x`, `./...`) is a directory.
const dirLike = (a: string) => a.endsWith('/') || !/\.\w+$/.test(a.split('/').pop() ?? a)

// scripts/test-files.sh runs the whole suite with --all (or no files), so it counts like the runner it wraps.
export const DEFAULT_SUITE_COMMANDS = ['claude plugin test', 'npm run check', 'npm test', 'npm run test', 'sh scripts/test-files.sh', 'bash scripts/test-files.sh', 'test-files.sh']

const basename = (w: string) => w.split('/').pop() ?? w

// A trailing "." in a pattern ("claude plugin test .") only says "the whole suite": drop it so
// that `claude plugin test tests/*.test.ts` is judged by its arguments like the rest.
function tokensOf(pattern: string): string[] {
  const t = pattern.trim().split(/\s+/).filter(Boolean)
  return t.length > 1 && t[t.length - 1] === '.' ? t.slice(0, -1) : t
}

// `--help`, `-h` and `--version` only print text: not a run of anything.
const INFO_FLAGS = new Set(['--help', '-h', '--version'])
const infoOnly = (args: string[]) => args.some(a => INFO_FLAGS.has(a))

function suiteArgs(args: string[]): boolean {
  if (infoOnly(args)) return false
  if (args.includes('--all')) return true
  // `--jobs 4` takes a value that is not a file.
  const rest = args.filter((a, i) => !a.startsWith('-') && args[i - 1] !== '--jobs')
  if (rest.length === 0) return true
  if (rest.some(a => GLOB.test(a) || dirLike(a))) return true
  return rest.length > MAX_FILES
}

// The first segment of `command` that runs a whole suite, as text, or undefined.
export const suiteRun = (command: string, patterns: string[]): string | undefined => segmentRun(command, patterns, suiteArgs)

export const DEFAULT_TYPECHECK_COMMANDS = ['npm run typecheck', 'tsc', 'npx tsc']

// The first segment of `command` that starts a typecheck, as text, or undefined. Whatever follows
// the command is irrelevant (`tsc -p .` and `tsc` are the same load), except help and version.
export const typecheckRun = (command: string, patterns: string[]): string | undefined => segmentRun(command, patterns, args => !infoOnly(args))

function segmentRun(command: string, patterns: string[], judge: (args: string[]) => boolean, depth = 0): string | undefined {
  if (depth > MAX_DEPTH || patterns.length === 0) return undefined
  const pats = patterns.map(tokensOf).filter(t => t.length > 0)
  for (const pipeline of parse(command)) {
    for (const cmd of pipeline) {
      for (const sub of cmd.subs) {
        const hit = segmentRun(sub, patterns, judge, depth + 1)
        if (hit !== undefined) return hit
      }
      const { words } = resolve(cmd.words)
      if (words.length === 0) continue
      const script = innerScript(basename(words[0]!), words.slice(1))
      if (script !== undefined) {
        const hit = segmentRun(script, patterns, judge, depth + 1)
        if (hit !== undefined) return hit
      }
      const norm = [basename(words[0]!), ...words.slice(1)]
      for (const p of pats) {
        if (p.length > norm.length || !p.every((tok, i) => tok === norm[i])) continue
        if (judge(norm.slice(p.length))) return words.join(' ')
      }
    }
  }
  return undefined
}

// The deny text for a whole-suite run, or undefined when `key` holds a confirmed slot.
// Holders are judged after reapSlots: an ended agent or an expired lease holds nothing, and an
// unconfirmed grant does not count until the agent calls acquire.
export function slotRefusal(state: TestSlots, rows: AgentRow[], key: string, limit: number, t: number, segment: string): string | undefined {
  const live = reapSlots(state, rows, t).state
  const mine = live.holders.find(h => h.key === key)
  if (mine !== undefined && mine.claimed !== false) return undefined
  const held = live.holders.length
    ? `Held now (${live.holders.length}/${limit}): ${live.holders.map(h => heldBy(h, t)).join(', ')}.`
    : 'The slots are free, so acquire is instant.'
  const how = mine !== undefined
    ? 'Your slot is granted but unconfirmed: call mcp__flow__test_slot action "acquire" once to confirm it.'
    : 'Call mcp__flow__test_slot action "acquire" first, and "release" when the run is over.'
  return `flow: \`${segment}\` runs a whole suite. ${how} ${held}`
}

// Workers run the test files they touched, never the whole suite: the reviewer's full check does
// that. Applies even when the worker holds a slot. Undefined for any other caller.
export function workerSuiteRefusal(isWorker: boolean, segment: string): string | undefined {
  if (!isWorker) return undefined
  return `flow: \`${segment}\` runs the whole suite, which only the reviewer's full check does. Run just the test files you added or changed. \`claude plugin test\` takes a folder, not files, so use \`sh scripts/test-files.sh tests/<name>.test.ts ...\` (it runs only those files), or your runner's own file arguments.`
}

// The deny text for a typecheck, or undefined when `key` holds a confirmed typecheck slot. A
// test-slot holder may typecheck too: the reviewer's full check includes one and must not deadlock.
export function typecheckRefusal(tc: TestSlots, tests: TestSlots, rows: AgentRow[], key: string, limit: number, t: number, segment: string): string | undefined {
  const holds = (s: TestSlots) => s.holders.some(h => h.key === key && h.claimed !== false)
  if (holds(reapSlots(tests, rows, t).state)) return undefined
  const live = reapTypecheck(tc, rows, t).state
  const mine = live.holders.find(h => h.key === key)
  if (mine !== undefined && mine.claimed !== false) return undefined
  const held = live.holders.length
    ? `Held now (${live.holders.length}/${limit}): ${live.holders.map(h => heldBy(h, t)).join(', ')}.`
    : 'The slots are free, so acquire is instant.'
  const how = mine !== undefined
    ? 'Your slot is granted but unconfirmed: call mcp__flow__test_slot kind "typecheck" action "acquire" once to confirm it.'
    : 'Call mcp__flow__test_slot with kind "typecheck", action "acquire" first, and "release" when it is over.'
  return `flow: \`${segment}\` is a typecheck. ${how} ${held}`
}

files.hooks/guards.ts:
// The two guards the plugin's tool.call hook runs for every agent of the flow, the main
// session included: broad process kills, and writes to the repo's main checkout. Both were
// rules in the prompts first; a rule the model reads can be skipped, a hook can't.
//
// The shell parse follows orca-flow's process_guard.py: small and conservative. It looks at
// words in command position (after `;`, `&&`, `||`, `|`, newlines, inside `$(…)`/backticks,
// behind sudo/xargs/env and friends, and in `sh -c` / `eval` strings). A missed case is better
// than refusing `grep pkill file` or `echo "kill 0"`.

type Cmd = {
  // Quotes removed; a command substitution is left as a placeholder.
  words: string[]
  // Source of each $(…) / `…` / <(…) inside this command.
  subs: string[]
  // Targets of output redirections (`> f`, `>> f`, `&> f`, `2> f`).
  outputs: string[]
}

const KEYWORDS = new Set(['{', '}', '!', 'if', 'then', 'else', 'elif', 'do', 'while', 'until', 'time', 'coproc'])
// Commands that run their arguments as a command; options are skipped up to the real command.
const WRAPPERS = new Set(['sudo', 'doas', 'nohup', 'exec', 'command', 'builtin', 'nice', 'caffeinate',
  'timeout', 'gtimeout', 'env', 'xargs', 'stdbuf'])
// Wrapper options that take a separate value, so the value isn't mistaken for the command.
const OPTS_WITH_VALUE: Record<string, Set<string>> = {
  sudo: new Set(['-u', '-g', '-p', '-C', '-h', '-U', '-r', '-t', '-D']),
  doas: new Set(['-u', '-C']),
  nice: new Set(['-n']),
  timeout: new Set(['-s', '-k', '--signal', '--kill-after']),
  gtimeout: new Set(['-s', '-k', '--signal', '--kill-after']),
  env: new Set(['-u', '-C', '-S', '--unset', '--chdir']),
  xargs: new Set(['-I', '-J', '-L', '-n', '-P', '-s', '-E', '-R', '-S', '-d', '-a', '--delimiter',
    '--arg-file', '--max-args', '--max-procs', '--replace']),
  stdbuf: new Set(['-i', '-o', '-e']),
}
const SHELLS = new Set(['sh', 'bash', 'zsh', 'dash', 'ksh'])
const ASSIGNMENT = /^[A-Za-z_][A-Za-z0-9_]*=/
export const MAX_DEPTH = 5

const basename = (w: string) => w.split('/').pop() ?? w

// A heredoc operator at s[i] ('<<' or '<<-' plus its delimiter word).
function heredocStart(s: string, i: number): { delim: string; stripTabs: boolean; end: number } {
  i += 2
  const stripTabs = s.startsWith('-', i)
  if (stripTabs) i += 1
  while (i < s.length && (s[i] === ' ' || s[i] === '\t')) i += 1
  const m = /^(['"]?)([^\s;&|<>()'"]*)\1/.exec(s.slice(i))!
  return { delim: m[2]!, stripTabs, end: i + m[0].length }
}

// From the start of the line after a heredoc operator, skips each body through its delimiter.
function skipHeredocBodies(s: string, i: number, heredocs: { delim: string; stripTabs: boolean }[]): number {
  const n = s.length
  for (const { delim, stripTabs } of heredocs) {
    while (i < n) {
      const j = s.indexOf('\n', i)
      const line = j < 0 ? s.slice(i) : s.slice(i, j)
      i = j < 0 ? n : j + 1
      if ((stripTabs ? line.replace(/^\t+/, '') : line) === delim) break
    }
  }
  return i
}

// Index of the ')' closing a '(' just before i; s.length when unbalanced.
function matchParen(s: string, i: number): number {
  let depth = 1
  const n = s.length
  let heredocs: { delim: string; stripTabs: boolean }[] = []
  while (i < n) {
    const c = s[i]!
    if (c === '\\') { i += 2; continue }
    // Heredoc bodies are prose (commit messages): an apostrophe in "don't" is not a quote.
    if (s.startsWith('<<', i) && !s.startsWith('<<<', i)) {
      const h = heredocStart(s, i)
      heredocs.push(h)
      i = h.end
      continue
    }
    if (c === '\n' && heredocs.length > 0) {
      i = skipHeredocBodies(s, i + 1, heredocs)
      heredocs = []
      continue
    }
    if (c === "'" || c === '"') {
      const j = s.indexOf(c, i + 1)
      i = j < 0 ? n : j + 1
      continue
    }
    if (c === '(') depth += 1
    else if (c === ')') {
      depth -= 1
      if (depth === 0) return i
    }
    i += 1
  }
  return n
}

// Splits a shell command line into pipelines of simple commands.
export function parse(s: string): Cmd[][] {
  const pipelines: Cmd[][] = []
  let pipe: Cmd[] = []
  let words: string[] = []
  let subs: string[] = []
  let outputs: string[] = []
  // null: no word in progress (so '' from "" still counts as a word).
  let word: string | null = null
  // The next word is a redirection target: an output's is kept, an input's dropped.
  let target: 'out' | 'in' | null = null
  let heredocs: { delim: string; stripTabs: boolean }[] = []
  let i = 0
  const n = s.length

  const endWord = () => {
    if (word !== null) {
      if (target === 'out') outputs.push(word)
      else if (target === null) words.push(word)
      target = null
    }
    word = null
  }
  const endCmd = () => {
    endWord()
    if (words.length || subs.length || outputs.length) pipe.push({ words, subs, outputs })
    words = []
    subs = []
    outputs = []
  }
  const endPipe = () => {
    endCmd()
    if (pipe.length) pipelines.push(pipe)
    pipe = []
  }

  while (i < n) {
    const c = s[i]!
    if (c === ' ' || c === '\t') {
      endWord()
      i += 1
    } else if (c === '\n') {
      endPipe()
      // Heredoc bodies are data, not commands: `cat <<EOF` … `pkill` … `EOF` is fine.
      i = skipHeredocBodies(s, i + 1, heredocs)
      heredocs = []
    } else if (c === '#' && word === null) {
      const j = s.indexOf('\n', i)
      i = j < 0 ? n : j
    } else if (c === "'") {
      let j = s.indexOf("'", i + 1)
      if (j < 0) j = n
      word = (word ?? '') + s.slice(i + 1, j)
      i = j + 1
    } else if (c === '"') {
      const buf: string[] = []
      i += 1
      while (i < n && s[i] !== '"') {
        if (s[i] === '\\' && i + 1 < n) {
          buf.push(s[i + 1]!)
          i += 2
        } else if (s.startsWith('$(', i)) {
          const j = matchParen(s, i + 2)
          if (!s.startsWith('$((', i)) subs.push(s.slice(i + 2, j))
          buf.push('$(…)')
          i = j + 1
        } else if (s[i] === '`') {
          let j = s.indexOf('`', i + 1)
          if (j < 0) j = n
          subs.push(s.slice(i + 1, j))
          buf.push('`…`')
          i = j + 1
        } else {
          buf.push(s[i]!)
          i += 1
        }
      }
      word = (word ?? '') + buf.join('')
      i += 1
    } else if (c === '\\') {
      // Backslash-newline is a line continuation.
      if (s[i + 1] !== '\n') word = (word ?? '') + (s[i + 1] ?? '')
      i += 2
    } else if (s.startsWith('$(', i)) {
      const j = matchParen(s, i + 2)
      // $((…)) is arithmetic, not a command.
      if (!s.startsWith('$((', i)) subs.push(s.slice(i + 2, j))
      word = (word ?? '') + '$(…)'
      i = j + 1
    } else if (s.startsWith('<(', i) || s.startsWith('>(', i)) {
      endWord()
      const j = matchParen(s, i + 2)
      subs.push(s.slice(i + 2, j))
      i = j + 1
    } else if (c === '`') {
      let j = s.indexOf('`', i + 1)
      if (j < 0) j = n
      subs.push(s.slice(i + 1, j))
      word = (word ?? '') + '`…`'
      i = j + 1
    } else if (s.startsWith('<<', i) && !s.startsWith('<<<', i)) {
      endWord()
      const h = heredocStart(s, i)
      heredocs.push(h)
      i = h.end
    } else if (c === '<' || c === '>') {
      // A redirection: drop the fd number before it, keep an output's target.
      if (word !== null && /^\d+$/.test(word)) word = null
      endWord()
      const m = /^[<>]+\|?(&(\d+|-)?)?/.exec(s.slice(i))!
      i += m[0].length
      // 2>&1 and >&- carry their target in the operator.
      if (!m[2]) target = m[0].includes('>') ? 'out' : 'in'
    } else if (c === '|') {
      if (s.startsWith('||', i)) {
        endPipe()
        i += 2
      } else {
        endCmd()
        i += s.startsWith('|&', i) ? 2 : 1
      }
    } else if (c === '&') {
      if (s.startsWith('&>', i)) {
        endWord()
        i += s.startsWith('&>>', i) ? 3 : 2
        target = 'out'
      } else {
        endPipe()
        i += s.startsWith('&&', i) ? 2 : 1
      }
    } else if (c === ';' || c === '(' || c === ')') {
      endPipe()
      i += 1
    } else {
      word = (word ?? '') + c
      i += 1
    }
  }
  endPipe()
  return pipelines
}

// The command words from the real command on, and whether it runs under xargs.
export function resolve(words: string[]): { words: string[]; viaXargs: boolean } {
  let i = 0
  let viaXargs = false
  while (i < words.length) {
    const w = words[i]!
    if (KEYWORDS.has(w) || ASSIGNMENT.test(w)) { i += 1; continue }
    const name = basename(w)
    if (!WRAPPERS.has(name)) return { words: words.slice(i), viaXargs }
    viaXargs ||= name === 'xargs'
    const takesValue = OPTS_WITH_VALUE[name] ?? new Set<string>()
    i += 1
    while (i < words.length) {
      const o = words[i]!
      if (o === '--') { i += 1; break }
      if (name === 'env' && ASSIGNMENT.test(o)) i += 1
      else if (o.startsWith('-') && o.length > 1) i += takesValue.has(o) ? 2 : 1
      else if ((name === 'timeout' || name === 'gtimeout') && /^\d/.test(o)) { i += 1; break }
      else break
    }
  }
  return { words: [], viaXargs }
}

// The script a shell runs with -c, or eval's arguments.
export function innerScript(name: string, args: string[]): string | undefined {
  if (name === 'eval') return args.join(' ')
  if (!SHELLS.has(name)) return undefined
  const k = args.findIndex(a => /^-[a-zA-Z]*c[a-zA-Z]*$/.test(a))
  return k >= 0 ? args[k + 1] : undefined
}

// --- Process guard -------------------------------------------------------------------------

const FIND_PID = 'Find the pid of the one process you started (`lsof -i :PORT`, `pgrep -fl <pattern>`) and `kill <pid>`.'

export const PKILL_REFUSAL = 'flow: pkill and killall are refused. Every flow agent runs in this one Claude Code session, ' +
  'and a kill by name or pattern reaches other agents\' processes and the session itself; on macOS pkill also reads ' +
  'options after the pattern as more patterns (`pkill -f X -n -u 501` once matched every session). ' +
  'Don\'t swap in `kill $(pgrep -f …)` either: same matching. ' + FIND_PID

export const PID_REFUSAL = 'flow: this kill is refused. Pid -1 signals every process you own (this session included), ' +
  '0 or a negative pid signals a whole process group, and 1 is launchd. ' + FIND_PID

export const LSOF_REFUSAL = 'flow: this kill is refused. lsof without -sTCP:LISTEN lists a port\'s clients as well as ' +
  'its server, so it can hit processes that aren\'t yours. Ask for the listening server only: ' +
  '`kill $(lsof -tiTCP:<port> -sTCP:LISTEN)`, or ' + FIND_PID.charAt(0).toLowerCase() + FIND_PID.slice(1)

function lsofWithoutListen(cmd: Cmd): boolean {
  const { words } = resolve(cmd.words)
  if (words.length === 0 || basename(words[0]!) !== 'lsof') return false
  // -sTCP:LISTEN, or -s TCP:LISTEN as two words.
  return !words.slice(1).some(w => w.toUpperCase().includes('TCP:LISTEN'))
}

// The pids a `kill` call signals; the signal spec and options are skipped.
function killTargets(args: string[]): string[] {
  if (args[0] === '-l' || args[0] === '-L') return []
  const pids: string[] = []
  let i = 0
  while (i < args.length) {
    const a = args[i]!
    if (a === '--') return [...pids, ...args.slice(i + 1)]
    if (i === 0 && (a === '-s' || a === '-n')) { i += 2; continue }
    // -9, -KILL, -SIGTERM: the signal; anything after it is a pid, -1 included.
    if (i === 0 && a.startsWith('-') && a.length > 1) { i += 1; continue }
    pids.push(a)
    i += 1
  }
  return pids
}

// Why a command line is refused as a broad process kill, or undefined.
export function killRefusal(command: string, depth = 0): string | undefined {
  if (depth > MAX_DEPTH) return undefined
  for (const pipeline of parse(command)) {
    for (const [idx, cmd] of pipeline.entries()) {
      for (const sub of cmd.subs) {
        const why = killRefusal(sub, depth + 1)
        if (why !== undefined) return why
      }
      const { words, viaXargs } = resolve(cmd.words)
      if (words.length === 0) continue
      const name = basename(words[0]!)
      const args = words.slice(1)
      if (name === 'pkill' || name === 'killall') return PKILL_REFUSAL
      const script = innerScript(name, args)
      if (script !== undefined) {
        const why = killRefusal(script, depth + 1)
        if (why !== undefined) return why
      }
      if (name !== 'kill') continue
      // A bare `kill -1` is HUP to no pid on some shells and every process on others: refuse it too.
      if (args.length === 1 && args[0] === '-1') return PID_REFUSAL
      if (killTargets(args).some(p => p === '0' || p === '1' || /^-\d+$/.test(p))) return PID_REFUSAL
      const fedBy = cmd.subs.flatMap(sub => parse(sub).flat())
      if (viaXargs) fedBy.push(...pipeline.slice(0, idx))
      if (fedBy.some(lsofWithoutListen)) return LSOF_REFUSAL
    }
  }
  return undefined
}

// --- Remote-ref delete guard -----------------------------------------------------------------

export const DELETE_REFUSAL = 'flow: do not delete a remote branch yourself. The plugin deletes each merged branch when the reviewer calls mcp__flow__reviewer action "done", and only after the merge is confirmed pushed.'

// Why a command line is refused as a `git push` that deletes a remote ref (--delete, -d, or a
// `:ref` refspec), or undefined. A chain with one such push is refused as a whole.
export function remoteDeleteRefusal(command: string, depth = 0): string | undefined {
  if (depth > MAX_DEPTH) return undefined
  for (const pipeline of parse(command)) {
    for (const cmd of pipeline) {
      for (const sub of cmd.subs) {
        const why = remoteDeleteRefusal(sub, depth + 1)
        if (why !== undefined) return why
      }
      const { words } = resolve(cmd.words)
      if (words.length === 0) continue
      const name = basename(words[0]!)
      const args = words.slice(1)
      const script = innerScript(name, args)
      if (script !== undefined) {
        const why = remoteDeleteRefusal(script, depth + 1)
        if (why !== undefined) return why
      }
      if (name !== 'git') continue
      let k = 0
      while (k < args.length && args[k]!.startsWith('-')) k += ['-C', '-c', '--git-dir', '--work-tree'].includes(args[k]!) ? 2 : 1
      if (args[k] !== 'push') continue
      const rest = args.slice(k + 1)
      if (rest.some(a => a === '--delete' || /^-[a-zA-Z]*d[a-zA-Z]*$/.test(a) || /^\+?:./.test(a))) return DELETE_REFUSAL
    }
  }
  return undefined
}

// --- Main-checkout guard -------------------------------------------------------------------

// A path a command writes: a file, or for git a directory whose checkout it changes.
export type WriteTarget = { path: string; git?: true }

// git subcommands that change the working tree or the checked-out branch. `pull` stays
// allowed: fast-forwarding the main checkout to its base is how it stays current. The plugin
// does that itself after a reviewer batch (hooks/mainff.ts), outside these guards.
const GIT_WRITES = new Set(['commit', 'merge', 'rebase', 'cherry-pick', 'revert', 'am', 'apply',
  'reset', 'restore', 'checkout', 'switch', 'stash'])
const GIT_STASH_READS = new Set(['list', 'show'])

export function normalize(path: string): string {
  const out: string[] = []
  for (const part of path.split('/')) {
    if (part === '' || part === '.') continue
    if (part === '..') out.pop()
    else out.push(part)
  }
  return '/' + out.join('/')
}

// An absolute path for a word, or undefined when the shell would expand it or the base is unknown.
export function resolvePath(word: string, cwd: string | undefined): string | undefined {
  if (word === '' || /[$`…*?~]/.test(word)) return undefined
  if (word.startsWith('/')) return normalize(word)
  return cwd === undefined ? undefined : normalize(`${cwd}/${word}`)
}

const options = (args: string[]) => args.filter(a => a.startsWith('-') && a !== '-')
const operands = (args: string[]) => args.filter(a => !a.startsWith('-') || a === '-')

// The files a sed or perl call edits in place; none when it doesn't edit in place.
function inPlaceTargets(args: string[]): string[] {
  const inPlace = args.some(a => a === '--in-place' || a.startsWith('--in-place=') || /^-[a-zA-Z]*i/.test(a))
  if (!inPlace) return []
  const files: string[] = []
  let script = false
  for (let k = 0; k < args.length; k++) {
    const a = args[k]!
    // An -e/-f option takes the next word as the script (perl's -pe too).
    if (/^-[a-zA-Z]*[ef]$/.test(a)) { k += 1; script = true; continue }
    if (a.startsWith('-')) continue
    // macOS `sed -i '' …`: the empty backup suffix.
    if (a === '') continue
    files.push(a)
  }
  return script ? files : files.slice(1)
}

// The paths a command line writes, resolved against cwd as `cd` moves it; relative paths are
// dropped when cwd is unknown.
export function writeTargets(command: string, cwd: string | undefined, depth = 0): WriteTarget[] {
  if (depth > MAX_DEPTH) return []
  const found: WriteTarget[] = []
  const add = (word: string, base: string | undefined, git?: true) => {
    const path = resolvePath(word, base)
    if (path !== undefined && !path.startsWith('/dev/')) found.push(git ? { path, git } : { path })
  }
  for (const pipeline of parse(command)) {
    for (const cmd of pipeline) {
      for (const sub of cmd.subs) found.push(...writeTargets(sub, cwd, depth + 1))
      for (const out of cmd.outputs) add(out, cwd)
      const { words } = resolve(cmd.words)
      if (words.length === 0) continue
      const name = basename(words[0]!)
      const args = words.slice(1)
      const script = innerScript(name, args)
      if (script !== undefined) found.push(...writeTargets(script, cwd, depth + 1))
      switch (name) {
        case 'cd': {
          const to = args.find(a => a !== '-P' && a !== '-L')
          cwd = to === undefined || to === '-' ? undefined : resolvePath(to, cwd)
          break
        }
        case 'tee': case 'rm': case 'touch':
          for (const a of operands(args)) add(a, cwd)
          break
        case 'cp': case 'mv': case 'install': {
          const ops = operands(args)
          if (ops.length >= 2 && !options(args).some(o => o === '-t' || o.startsWith('--target-directory'))) add(ops.at(-1)!, cwd)
          break
        }
        case 'sed': case 'gsed': case 'perl':
          for (const f of inPlaceTargets(args)) add(f, cwd)
          break
        case 'git': {
          let dir = cwd
          let k = 0
          while (k < args.length && args[k]!.startsWith('-')) {
            const o = args[k]!
            if (o === '-C') { dir = args[k + 1] === undefined ? undefined : resolvePath(args[k + 1]!, dir); k += 2 }
            else if (o === '-c' || o === '--git-dir' || o === '--work-tree') { k += 2 }
            else k += 1
          }
          const sub = args[k]
          if (sub === undefined || !GIT_WRITES.has(sub)) break
          if (sub === 'stash' && GIT_STASH_READS.has(args[k + 1] ?? '')) break
          if (dir !== undefined) found.push({ path: dir, git: true })
          break
        }
      }
    }
  }
  return found
}

// The repo's checkouts as `git worktree list --porcelain` gives them: the main one first.
export type Checkouts = { main: string; worktrees: string[] }

export function parseWorktrees(porcelain: string): Checkouts | undefined {
  const paths = porcelain.split('\n\n')
    .filter(block => !/^bare$/m.test(block))
    .map(block => /^worktree (.+)$/m.exec(block)?.[1])
    .filter((p): p is string => p !== undefined)
    .map(normalize)
  if (paths.length === 0) return undefined
  return { main: paths[0]!, worktrees: paths.slice(1) }
}

const under = (path: string, dir: string) => path === dir || path.startsWith(dir === '/' ? '/' : `${dir}/`)

// The path relative to the main checkout when it lies there; undefined in a linked worktree,
// in .git/, or outside the repo.
export function mainRelative(path: string, co: Checkouts): string | undefined {
  const p = normalize(path)
  if (!under(p, co.main) || under(p, `${co.main}/.git`)) return undefined
  if (co.worktrees.some(w => w !== co.main && under(p, w))) return undefined
  return p === co.main ? '' : p.slice(co.main.length + 1)
}

// `main_checkout_allow` as a list: comma or newline separated, each a file or, ending in `/`,
// a directory, relative to the main checkout.
export function allowList(setting: string): string[] {
  return setting.split(/[,\n]/).map(s => s.trim().replace(/^\.\//, '')).filter(s => s !== '')
}

export function allowed(rel: string, allow: string[]): boolean {
  return allow.some(a => a.endsWith('/') ? rel.startsWith(a) : rel === a || rel.startsWith(`${a}/`))
}

// Flow has work in this repo when one of its worktrees (under <main>/.claude/worktrees/) exists;
// the user's own worktree elsewhere doesn't count.
export function flowActive(co: Checkouts): boolean {
  return co.worktrees.some(w => under(w, `${co.main}/.claude/worktrees`) && w !== `${co.main}/.claude/worktrees`)
}

export function mainCheckoutRefusal(main: string, what: string, allow: string[]): string {
  return `flow: ${what} is in the repo's main checkout. "Main checkout" means the repo's original folder (${main}), ` +
    'not the main branch: the branch you are on and pushes are irrelevant. It is guarded because flow has work in this repo ' +
    '(a worktree under .claude/worktrees/ or a live flow agent). ' +
    'Build the change in a worker\'s worktree: put it in a flow:worker\'s brief, or send it to the worker whose worktree owns the file. ' +
    `Still writable there: ${allow.length ? allow.join(', ') : 'nothing'}. ` +
    'Don\'t route around this through another tool or a shell command. If the user wants the main checkout changed, ' +
    'tell them the exact fix: set main_checkout_guard to false to turn the guard off, or list the files or directories to keep writable in ' +
    'main_checkout_allow, via /config -> flow, or in a settings file (.claude/flow.json, or the personal .g\u0069t/flow/config.json).'
}

files.hooks/branchdelete.ts:
// Deleting a merged PR branch on the remote. The reviewer used to chain `git push && git push origin
// --delete <branch>`; a rejected push still deleted the branch and GitHub closed the PR for good. So
// the plugin deletes, when the reviewer reports "done", and only once the branch tip is in origin/<base>.
import type { GitRunner, Run } from './mainff'

const reason = (r: Run): string => (r.stderr.trim() || r.stdout.trim()).split('\n')[0]?.slice(0, 160) || `exit ${r.exitCode}`
const kept = (branch: string, why: string): string => `branch ${branch} kept: ${why}`
// A plain branch name: no option-like, revision or refspec syntax can slip into the git argv.
const SAFE_BRANCH = /^[A-Za-z0-9][A-Za-z0-9._/-]*$/

// One line: "branch <b> deleted", "branch <b> already gone" or "branch <b> kept: <why>". Never throws.
export async function deleteMergedBranch(git: GitRunner, branch: string | undefined, base: string): Promise<string> {
  const b = (branch ?? '').trim()
  if (b === '') return kept('?', 'no branch recorded')
  try {
    if (!SAFE_BRANCH.test(b) || b.includes('..') || b.endsWith('.lock')) return kept(b, 'not a plain branch name')
    if (b === base || b === `origin/${base}`) return kept(b, 'it is the base branch')
    const ls = await git(['git', 'ls-remote', '--heads', 'origin', `refs/heads/${b}`])
    if (ls.exitCode !== 0) return kept(b, `ls-remote failed: ${reason(ls)}`)
    const tip = ls.stdout.trim().split('\n')[0]?.split(/\s+/)[0] ?? ''
    if (tip === '') return `branch ${b} already gone`
    if (!/^[0-9a-f]{40,64}$/.test(tip)) return kept(b, 'unreadable remote tip')
    const fb = await git(['git', 'fetch', 'origin', `+refs/heads/${base}:refs/remotes/origin/${base}`, `refs/heads/${b}`])
    if (fb.exitCode !== 0) return kept(b, `fetch failed: ${reason(fb)}`)
    // Exit 0: merged; 1: not an ancestor; anything else: git could not tell.
    const anc = await git(['git', 'merge-base', '--is-ancestor', tip, `refs/remotes/origin/${base}`])
    if (anc.exitCode === 1) return kept(b, `not merged into origin/${base}`)
    if (anc.exitCode !== 0) return kept(b, `ancestry check failed: ${reason(anc)}`)
    // The lease makes the delete fail if the branch moved since the tip we checked.
    const del = await git(['git', 'push', `--force-with-lease=refs/heads/${b}:${tip}`, 'origin', `:refs/heads/${b}`])
    if (del.exitCode !== 0) return kept(b, `push failed: ${reason(del)}`)
    return `branch ${b} deleted`
  } catch (err) {
    return kept(b, `delete failed: ${(err instanceof Error ? err.message : String(err)).split('\n')[0]?.slice(0, 160) ?? ''}`)
  }
}

